from __future__ import annotations

from copy import deepcopy
from enum import Enum
from pathlib import Path
from typing import Any, Dict, List, Optional, Tuple, Union

import yaml
from pydantic.v1 import BaseModel, BaseSettings, Field, PrivateAttr


def _merge_dictionaries(dict1: dict, dict2: dict) -> dict:
    """Recursive merge dictionaries."""

    if dict2 is None:
        return deepcopy(dict1)
    for key, value in dict1.items():
        if isinstance(value, dict):
            dict2[key] = _merge_dictionaries(value, dict2.get(key, {}))
        elif key not in dict2:
            dict2[key] = deepcopy(value)
    return dict2


class Dataset(BaseModel):
    description: str = ""
    creator: str = ""
    author: str = ""
    copyright_holder: str = ""
    copyright_year: str = ""
    url: str = ""


class NumVars(BaseModel):
    quantiles: List[float] = Field(default_factory=lambda: [0.05, 0.25, 0.5, 0.75, 0.95])
    skewness_threshold: int = 20
    low_categorical_threshold: int = 5
    chi_squared_threshold: float = 0.999


class TextVars(BaseModel):
    length: bool = True
    words: bool = True
    characters: bool = True
    redact: bool = False


class CatVars(BaseModel):
    length: bool = True
    characters: bool = True
    words: bool = True
    cardinality_threshold: int = 50
    percentage_cat_threshold: float = 0.5
    imbalance_threshold: float = 0.5
    n_obs: int = 5
    chi_squared_threshold: float = 0.999
    coerce_str_to_date: bool = False
    redact: bool = False
    histogram_largest: int = 50
    stop_words: List[str] = Field(default_factory=list)
    dirty_categories: bool = False
    dirty_categories_threshold: float = 0.85


class BoolVars(BaseModel):
    n_obs: int = 3
    imbalance_threshold: float = 0.5
    mappings: Dict[str, bool] = Field(
        default_factory=lambda: {
            "t": True,
            "f": False,
            "yes": True,
            "no": False,
            "y": True,
            "n": False,
            "true": True,
            "false": False,
        }
    )


class FileVars(BaseModel):
    active: bool = False


class PathVars(BaseModel):
    active: bool = False


class ImageVars(BaseModel):
    active: bool = False
    exif: bool = True
    hash: bool = True


class UrlVars(BaseModel):
    active: bool = False


class TimeseriesVars(BaseModel):
    active: bool = False
    sortby: Optional[str] = None
    autocorrelation: float = 0.7
    lags: List[int] = Field(default_factory=lambda: [1, 7, 12, 24, 30])
    significance: float = 0.05
    pacf_acf_lag: int = 100
    autolag: Optional[str] = "AIC"
    maxlag: Optional[int] = None


class Univariate(BaseModel):
    num: NumVars = Field(default_factory=NumVars)
    text: TextVars = Field(default_factory=TextVars)
    cat: CatVars = Field(default_factory=CatVars)
    image: ImageVars = Field(default_factory=ImageVars)
    bool: BoolVars = Field(default_factory=BoolVars)
    path: PathVars = Field(default_factory=PathVars)
    file: FileVars = Field(default_factory=FileVars)
    url: UrlVars = Field(default_factory=UrlVars)
    timeseries: TimeseriesVars = Field(default_factory=TimeseriesVars)


class MissingPlot(BaseModel):
    quantiles: List[float] = Field(default_factory=lambda: [0.05, 0.25, 0.5, 0.75, 0.95])
    skewness_threshold: int = 20
    low_categorical_threshold: int = 5
    chi_squared_threshold: float = 0.999


class ImageType(str, Enum):
    svg = "svg"
    png = "png"


class CorrelationPlot(BaseModel):
    cmap: str = "RdBu"
    bad: str = "#000000"


class Histogram(BaseModel):
    bins: int = 50
    max_bins: int = 250
    x_axis_labels: bool = True
    density: bool = False


class CatFrequencyPlot(BaseModel):
    show: bool = True
    type: str = "bar"
    max_unique: int = 10
    colors: Optional[List[str]] = None


class Plot(BaseModel):
    missing: MissingPlot = Field(default_factory=MissingPlot)
    image_format: ImageType = ImageType.svg
    correlation: CorrelationPlot = Field(default_factory=CorrelationPlot)
    dpi: int = 800
    histogram: Histogram = Field(default_factory=Histogram)
    scatter_threshold: int = 1000
    cat_freq: CatFrequencyPlot = Field(default_factory=CatFrequencyPlot)
    font_path: Optional[Union[Path, str]] = None


class Theme(str, Enum):
    united = "united"
    flatly = "flatly"
    cosmo = "cosmo"
    simplex = "simplex"


class Style(BaseModel):
    primary_colors: List[str] = Field(default_factory=lambda: ["#0d6efd", "#dc3545", "#198754"])
    logo: str = ""
    theme: Optional[Theme] = None
    _labels: List[str] = PrivateAttr(default_factory=lambda: ["_"])

    @property
    def primary_color(self) -> str:
        return self.primary_colors[0]


class Html(BaseModel):
    style: Style = Field(default_factory=Style)
    navbar_show: bool = True
    minify_html: bool = True
    use_local_assets: bool = True
    inline: bool = True
    assets_prefix: Optional[str] = None
    assets_path: Optional[str] = None
    full_width: bool = False


class Duplicates(BaseModel):
    head: int = 10
    key: str = "# duplicates"


class Correlation(BaseModel):
    key: str = ""
    calculate: bool = Field(default=True)
    warn_high_correlations: int = Field(default=10)
    threshold: float = Field(default=0.5)
    n_bins: int = Field(default=10)


class Interactions(BaseModel):
    continuous: bool = True
    targets: List[str] = Field(default_factory=list)


class Samples(BaseModel):
    head: int = 10
    tail: int = 10
    random: int = 0


class Variables(BaseModel):
    descriptions: dict = Field(default_factory=dict)


class IframeAttribute(str, Enum):
    src = "src"
    srcdoc = "srcdoc"


class Iframe(BaseModel):
    height: str = "800px"
    width: str = "100%"
    attribute: IframeAttribute = IframeAttribute.srcdoc


class Notebook(BaseModel):
    iframe: Iframe = Field(default_factory=Iframe)


class Report(BaseModel):
    precision: int = 8


def _default_correlations() -> Dict[str, Correlation]:
    return {
        "auto": Correlation(key="auto", calculate=True),
        "spearman": Correlation(key="spearman", calculate=False),
        "pearson": Correlation(key="pearson", calculate=False),
        "phi_k": Correlation(key="phi_k", calculate=False),
        "cramers": Correlation(key="cramers", calculate=False),
        "kendall": Correlation(key="kendall", calculate=False),
    }


class Settings(BaseSettings):
    title: str = "YData Profiling Report"
    dataset: Dataset = Field(default_factory=Dataset)
    variables: Variables = Field(default_factory=Variables)
    infer_dtypes: bool = True
    show_variable_description: bool = True
    pool_size: int = 0
    progress_bar: bool = True
    vars: Univariate = Field(default_factory=Univariate)
    sort: Optional[str] = None
    missing_diagrams: Dict[str, bool] = Field(
        default_factory=lambda: {"bar": True, "matrix": True, "heatmap": True}
    )
    correlation_table: bool = True
    correlations: Dict[str, Correlation] = Field(default_factory=_default_correlations)
    interactions: Interactions = Field(default_factory=Interactions)
    categorical_maximum_correlation_distinct: int = 100
    memory_deep: bool = False
    plot: Plot = Field(default_factory=Plot)
    duplicates: Optional[Duplicates] = Field(default_factory=Duplicates)
    samples: Optional[Samples] = Field(default_factory=Samples)
    reject_variables: bool = True
    n_obs_unique: int = 10
    n_freq_table_max: int = 10
    n_extreme_obs: int = 10
    report: Report = Field(default_factory=Report)
    html: Html = Field(default_factory=Html)
    notebook: Notebook = Field(default_factory=Notebook)

    class Config:
        env_prefix = "profile_"

    def update(self, updates: dict) -> "Settings":
        merged = _merge_dictionaries(self.dict(), deepcopy(updates))
        return Settings.parse_obj(merged)

    @staticmethod
    def from_file(config_file: Union[Path, str]) -> "Settings":
        data = yaml.safe_load(Path(config_file).read_text()) or {}
        return Settings.parse_obj(data)


class SparkSettings(Settings):
    vars: Univariate = Field(
        default_factory=lambda: Univariate(
            num=NumVars(low_categorical_threshold=0),
        )
    )
    infer_dtypes: bool = False
    correlations: Dict[str, Correlation] = Field(
        default_factory=lambda: {
            "spearman": Correlation(key="spearman", calculate=True),
            "pearson": Correlation(key="pearson", calculate=True),
        }
    )
    correlation_table: bool = True
    interactions: Interactions = Field(default_factory=lambda: Interactions(continuous=False))
    missing_diagrams: Dict[str, bool] = Field(
        default_factory=lambda: {"bar": False, "matrix": False, "dendrogram": False, "heatmap": False}
    )
    samples: Optional[Samples] = Field(default_factory=lambda: Samples(tail=0, random=0))


class Config:
    """Utility class for predefined configuration groups and shorthands."""

    arg_groups: Dict[str, Any] = {
        "sensitive": {
            "samples": None,
            "duplicates": None,
            "vars": {"cat": {"redact": True}, "text": {"redact": True}},
        },
        "flatly_theme": {
            "html": {"style": {"theme": Theme.flatly, "primary_colors": ["#2c3e50", "#dc3545", "#198754"]}}
        },
        "united_theme": {
            "html": {"style": {"theme": Theme.united, "primary_colors": ["#d34615", "#0d6efd", "#198754"]}}
        },
        "explorative": {
            "vars": {
                "cat": {"characters": True, "words": True},
                "url": {"active": True},
                "path": {"active": True},
                "file": {"active": True},
                "image": {"active": True},
            },
            "n_obs_unique": 10,
            "n_extreme_obs": 10,
            "n_freq_table_max": 10,
            "memory_deep": True,
        },
    }

    _shorthands: Dict[str, Any] = {
        "dataset": {
            "creator": "",
            "author": "",
            "description": "",
            "copyright_holder": "",
            "copyright_year": "",
            "url": "",
        },
        "samples": {"head": 0, "tail": 0, "random": 0},
        "duplicates": {"head": 0},
        "interactions": {"targets": [], "continuous": False},
        "missing_diagrams": {"bar": False, "matrix": False, "heatmap": False},
        "correlations": {
            "auto": {"calculate": False},
            "pearson": {"calculate": False},
            "spearman": {"calculate": False},
            "kendall": {"calculate": False},
            "phi_k": {"calculate": False},
            "cramers": {"calculate": False},
        },
        "correlation_table": True,
    }

    @staticmethod
    def get_arg_groups(key: str) -> dict:
        group = deepcopy(Config.arg_groups[key])
        expanded, _ = Config.shorthands(group, split=False)
        return expanded

    @staticmethod
    def shorthands(kwargs: dict, split: bool = True) -> Tuple[dict, dict]:
        source = deepcopy(kwargs)
        shorthand_args: dict = {}
        remaining = deepcopy(kwargs) if split else {}
        for key, replacement in Config._shorthands.items():
            if key not in source:
                continue
            value = source[key]
            if value is None or value is False:
                shorthand_args[key] = deepcopy(replacement)
                if split:
                    remaining.pop(key, None)
            elif split:
                remaining[key] = value
        if not split:
            merged = deepcopy(kwargs)
            for key, value in shorthand_args.items():
                merged[key] = value
            return merged, {}
        return shorthand_args, remaining

