from __future__ import annotations

import hashlib
import json
import re
import warnings
from pathlib import Path
from typing import Any, Optional

import pandas as pd

from ydata_profiling.utils.paths import get_data_path

HASH_PREFIX = "2@"


def rename_index(df: pd.DataFrame) -> pd.DataFrame:
    """If the DataFrame contains a column or index named `index`, rename it."""

    df = df.copy()
    if "index" in df.columns:
        df.rename(columns={"index": "df_index"}, inplace=True)
    if df.index.name == "index":
        df.index = df.index.rename("df_index")
    if getattr(df.index, "names", None):
        df.index.names = ["df_index" if name == "index" else name for name in df.index.names]
    return df


def hash_dataframe(df: pd.DataFrame) -> str:
    """Hash a DataFrame (implementation might change in the future)."""

    hashed = pd.util.hash_pandas_object(df, index=True).astype(str).str.cat(sep="\n")
    digest = hashlib.sha256(hashed.encode("utf-8")).hexdigest()
    return f"{HASH_PREFIX}{digest}"


def expand_mixed(df: pd.DataFrame, types: Any = None) -> pd.DataFrame:
    expanded = df.copy()
    for column in list(expanded.columns):
        sample = expanded[column].dropna().head(1)
        if sample.empty:
            continue
        value = sample.iloc[0]
        if isinstance(value, (dict, list, tuple)) and (types is None or isinstance(value, types)):
            nested = expanded[column].apply(
                lambda item: item if isinstance(item, dict) else dict(enumerate(item)) if isinstance(item, (list, tuple)) else {}
            )
            nested_df = nested.apply(pd.Series)
            nested_df = nested_df.add_prefix(f"{column}_")
            expanded = expanded.drop(columns=[column]).join(nested_df)
    return expanded


def is_supported_compression(file_extension: str) -> bool:
    return file_extension.lower() in {".bz2", ".gz", ".xz", ".zip"}


def uncompressed_extension(file_name: Path) -> str:
    suffixes = list(file_name.suffixes)
    if suffixes and is_supported_compression(suffixes[-1]):
        suffixes = suffixes[:-1]
    return suffixes[-1] if suffixes else ""


def warn_read(extension: str) -> None:
    warnings.warn(f"Unsupported extension '{extension}', falling back to pandas.read_csv when possible.")


def read_pandas(file_name: Path) -> pd.DataFrame:
    extension = uncompressed_extension(file_name)
    if extension in {".csv", ".txt", ""}:
        return pd.read_csv(file_name)
    if extension in {".json"}:
        return pd.read_json(file_name)
    if extension in {".xls", ".xlsx"}:
        return pd.read_excel(file_name)
    if extension in {".parquet"}:
        return pd.read_parquet(file_name)
    warn_read(extension)
    return pd.read_csv(file_name)


def sort_column_names(dct: dict, sort: Optional[str] = None) -> dict:
    if sort not in {"ascending", "descending", "asc", "desc"}:
        return dct
    reverse = sort in {"descending", "desc"}
    return {key: dct[key] for key in sorted(dct.keys(), reverse=reverse)}


def preprocess(config, df: Any) -> Any:
    from ydata_profiling.model.pandas import pandas_preprocess
    from ydata_profiling.model.spark import spark_preprocess

    if isinstance(df, pd.DataFrame):
        return pandas_preprocess(config, df)
    return spark_preprocess(config, df)


def redact_key(data: dict, config) -> dict:
    return {f"REDACTED_{index}": value for index, value in enumerate(data.values(), start=1)}


def redact_value(data: dict, config) -> dict:
    return {key: f"REDACTED_{index}" for index, key in enumerate(data.keys(), start=1)}


def get_custom_sample(sample: dict):
    from ydata_profiling.model.sample import Sample

    if not sample:
        return []
    return [
        Sample(
            name=sample.get("name", "Custom sample"),
            data=sample["data"],
            caption=sample.get("caption"),
        )
    ]


def slugify(value: str, allow_unicode: bool = False) -> str:
    value = str(value)
    if allow_unicode:
        value = re.sub(r"[^\w\s-]", "", value.lower())
    else:
        value = (
            value.encode("ascii", "ignore").decode("ascii")
            if not value.isascii()
            else value
        )
        value = re.sub(r"[^\w\s-]", "", value.lower())
    return re.sub(r"[-\s]+", "-", value).strip("-_")


def _redact_series_like(obj: Any) -> Any:
    if isinstance(obj, pd.Series):
        return pd.Series(["REDACTED"] * len(obj), index=obj.index)
    if isinstance(obj, pd.DataFrame):
        return pd.DataFrame("REDACTED", index=obj.index, columns=obj.columns)
    return obj


def redact_summary(summary: dict, config) -> dict:
    redacted = {}
    for key, value in summary.items():
        if key in {"value_counts_without_nan", "word_counts", "character_counts"} and hasattr(value, "index"):
            values = list(getattr(value, "values", []))
            redacted[key] = pd.Series(values, index=[f"REDACTED_{i}" for i in range(1, len(values) + 1)])
        elif key in {"first_rows"}:
            redacted[key] = _redact_series_like(value)
        elif isinstance(value, dict):
            redacted[key] = redact_summary(value, config)
        else:
            redacted[key] = value
    return redacted

