from __future__ import annotations

import os
from dataclasses import dataclass


SUPPRESS_BANNER = os.environ.get("YDATA_SUPPRESS_BANNER", "").lower() in {"1", "true", "yes"}
_displayed_banner = False


def in_jupyter_notebook() -> bool:
    """Check if the code is running inside a Jupyter Notebook."""

    try:
        from IPython import get_ipython

        shell = get_ipython()
        return shell is not None and shell.__class__.__name__ == "ZMQInteractiveShell"
    except Exception:
        return False


@dataclass
class DisplayInfo:
    title: str
    info_text: str
    link: str = "https://ydata.ai/register"

    def display_message(self) -> None:
        if in_jupyter_notebook():
            try:
                from IPython.display import HTML, display

                display(
                    HTML(
                        f"<div><strong>{self.title}</strong><br>{self.info_text}<br>"
                        f'<a href="{self.link}">{self.link}</a></div>'
                    )
                )
                return
            except Exception:
                pass
        print(f"{self.title}\n{self.info_text}\n{self.link}")


def display_banner() -> None:
    global _displayed_banner
    if SUPPRESS_BANNER or _displayed_banner:
        return
    DisplayInfo(
        title="ydata-profiling",
        info_text="Generate a profile report with HTML, JSON, or notebook-friendly output.",
        link="https://github.com/ydataai/ydata-profiling",
    ).display_message()
    _displayed_banner = True

