"""Small fallback subset of ipywidgets used by the tests."""

from __future__ import annotations

from dataclasses import dataclass
from typing import Any, Iterable, Tuple


@dataclass
class Layout:
    width: str | None = None
    height: str | None = None
    display: str | None = None
    grid_template_columns: str | None = None
    grid_gap: str | None = None
    align_items: str | None = None
    justify_content: str | None = None


class Widget:
    def __init__(self, *children: Any, **kwargs: Any) -> None:
        children_arg = kwargs.pop("children", children)
        self.children: Tuple[Any, ...] = tuple(children_arg)
        self.layout = kwargs.pop("layout", Layout())
        for key, value in kwargs.items():
            setattr(self, key, value)

    def __repr__(self) -> str:
        return f"{self.__class__.__name__}(children={len(self.children)})"


class Box(Widget):
    pass


class VBox(Box):
    pass


class HBox(Box):
    pass


class GridBox(Box):
    pass


class Accordion(Box):
    def __init__(self, *children: Any, **kwargs: Any) -> None:
        super().__init__(*children, **kwargs)
        self._titles: dict[int, str] = {}

    def set_title(self, index: int, title: str) -> None:
        self._titles[index] = title


class Tab(Accordion):
    pass


class HTML(Widget):
    def __init__(self, value: str = "", **kwargs: Any) -> None:
        super().__init__(**kwargs)
        self.value = value


class Output(Widget):
    def __enter__(self) -> "Output":
        return self

    def __exit__(self, exc_type: Any, exc: Any, tb: Any) -> None:
        return None


class FloatProgress(Widget):
    def __init__(
        self,
        value: float = 0.0,
        min: float = 0.0,
        max: float = 1.0,
        description: str = "",
        bar_style: str = "",
        **kwargs: Any,
    ) -> None:
        super().__init__(**kwargs)
        self.value = value
        self.min = min
        self.max = max
        self.description = description
        self.bar_style = bar_style


class ToggleButton(Widget):
    def __init__(self, value: bool = False, description: str = "", **kwargs: Any) -> None:
        super().__init__(**kwargs)
        self.value = value
        self.description = description


class Button(Widget):
    def __init__(self, description: str = "", button_style: str = "", **kwargs: Any) -> None:
        super().__init__(**kwargs)
        self.description = description
        self.button_style = button_style


class Label(Widget):
    def __init__(self, value: str = "", **kwargs: Any) -> None:
        super().__init__(**kwargs)
        self.value = value


class Dropdown(Widget):
    def __init__(self, options: Iterable[Any] = (), value: Any = None, **kwargs: Any) -> None:
        super().__init__(**kwargs)
        self.options = tuple(options)
        self.value = value


class GridspecLayout(GridBox):
    pass


__all__ = [
    "Accordion",
    "Box",
    "Button",
    "Dropdown",
    "FloatProgress",
    "GridBox",
    "GridspecLayout",
    "HBox",
    "HTML",
    "Label",
    "Layout",
    "Output",
    "Tab",
    "ToggleButton",
    "VBox",
    "Widget",
]

