from __future__ import annotations

from contextlib import contextmanager, nullcontext
from functools import lru_cache
from typing import Generator, Tuple

import pandas as pd


@lru_cache(maxsize=1)
def pandas_version_info() -> Tuple[int, ...]:
    return tuple(int(part) for part in str(pd.__version__).split(".") if part.isdigit())


@contextmanager
def optional_option_context(option_key: str, value: object) -> Generator[None, None, None]:
    """
    A context manager that sets an option only if it is available in the
    current pandas version; otherwise, it is a no-op.
    """

    try:
        with pd.option_context(option_key, value):
            yield
    except Exception:
        with nullcontext():
            yield

