def calculate_nrows(df: Any):
    try:
        import pandas as pd

        if isinstance(df, pd.DataFrame):
            return len(df)
    except Exception:
        pass

    if hasattr(df, "count"):
        try:
            return int(df.count())
        except Exception:
            return 0
    return 0


def _copy(self: Path, target):
