from __future__ import annotations

from dataclasses import asdict, is_dataclass
from pathlib import Path
from typing import Any, Callable, Dict, List, Type, Union

import numpy as np
import pandas as pd

from ydata_profiling.model.description import BaseDescription
from ydata_profiling.model.handler import Handler
from ydata_profiling.utils.dataframe import redact_summary as redact_summary_util


class BaseSummarizer(Handler):
    """A base summarizer."""

    def summarize(self, config, series: pd.Series, dtype: Type) -> dict:
        dtype_name = dtype if isinstance(dtype, str) else getattr(dtype, "__name__", str(dtype))
        summary = {"type": dtype_name}
        return self.handle(dtype_name, config, series, summary)


class ProfilingSummarizer(BaseSummarizer):
    """A summarizer for Pandas DataFrames."""

    def __init__(self, typeset, use_spark: bool = False):
        self.use_spark = use_spark
        super().__init__(self._create_summary_map(), typeset)

    @property
    def summary_map(self) -> Dict[str, List[Callable]]:
        return self.mapping

    def _create_summary_map(self) -> Dict[str, List[Callable]]:
        if self.use_spark:
            from ydata_profiling.model.spark import (
                describe_boolean_1d_spark,
                describe_categorical_1d_spark,
                describe_date_1d_spark,
                describe_numeric_1d_spark,
                describe_text_1d_spark,
                spark_describe_counts,
                spark_describe_generic,
                spark_describe_supported,
            )

            return {
                "Unsupported": [spark_describe_generic],
                "Numeric": [spark_describe_counts, spark_describe_generic, spark_describe_supported, describe_numeric_1d_spark],
                "DateTime": [spark_describe_counts, spark_describe_generic, spark_describe_supported, describe_date_1d_spark],
                "Text": [spark_describe_counts, spark_describe_generic, spark_describe_supported, describe_text_1d_spark],
                "Categorical": [spark_describe_counts, spark_describe_generic, spark_describe_supported, describe_categorical_1d_spark],
                "Boolean": [spark_describe_counts, spark_describe_generic, spark_describe_supported, describe_boolean_1d_spark],
                "URL": [spark_describe_counts, spark_describe_generic, spark_describe_supported, describe_text_1d_spark],
                "Path": [spark_describe_counts, spark_describe_generic, spark_describe_supported, describe_text_1d_spark],
                "File": [spark_describe_counts, spark_describe_generic, spark_describe_supported, describe_text_1d_spark],
                "Image": [spark_describe_counts, spark_describe_generic, spark_describe_supported, describe_text_1d_spark],
                "TimeSeries": [spark_describe_counts, spark_describe_generic, spark_describe_supported, describe_numeric_1d_spark],
            }

        from ydata_profiling.model.pandas import (
            pandas_describe_boolean_1d,
            pandas_describe_categorical_1d,
            pandas_describe_counts,
            pandas_describe_date_1d,
            pandas_describe_file_1d,
            pandas_describe_generic,
            pandas_describe_image_1d,
            pandas_describe_numeric_1d,
            pandas_describe_path_1d,
            pandas_describe_supported,
            pandas_describe_text_1d,
            pandas_describe_timeseries_1d,
            pandas_describe_url_1d,
        )

        return {
            "Unsupported": [pandas_describe_generic],
            "Numeric": [pandas_describe_counts, pandas_describe_generic, pandas_describe_supported, pandas_describe_numeric_1d],
            "DateTime": [pandas_describe_counts, pandas_describe_generic, pandas_describe_supported, pandas_describe_date_1d],
            "Text": [pandas_describe_counts, pandas_describe_generic, pandas_describe_supported, pandas_describe_text_1d],
            "Categorical": [pandas_describe_counts, pandas_describe_generic, pandas_describe_supported, pandas_describe_categorical_1d],
            "Boolean": [pandas_describe_counts, pandas_describe_generic, pandas_describe_supported, pandas_describe_boolean_1d],
            "URL": [pandas_describe_counts, pandas_describe_generic, pandas_describe_supported, pandas_describe_url_1d],
            "Path": [pandas_describe_counts, pandas_describe_generic, pandas_describe_supported, pandas_describe_path_1d],
            "File": [pandas_describe_counts, pandas_describe_generic, pandas_describe_supported, pandas_describe_file_1d],
            "Image": [pandas_describe_counts, pandas_describe_generic, pandas_describe_supported, pandas_describe_image_1d],
            "TimeSeries": [
                pandas_describe_counts,
                pandas_describe_generic,
                pandas_describe_supported,
                pandas_describe_numeric_1d,
                pandas_describe_timeseries_1d,
            ],
        }


def format_summary(summary: Union[BaseDescription, dict]) -> dict:
    def fmt(v: Any) -> Any:
        if is_dataclass(v):
            return {key: fmt(value) for key, value in asdict(v).items()}
        if isinstance(v, dict):
            return {str(key): fmt(value) for key, value in v.items()}
        if isinstance(v, list):
            return [fmt(item) for item in v]
        if isinstance(v, tuple):
            return [fmt(item) for item in v]
        if isinstance(v, pd.DataFrame):
            return v.to_dict(orient="records")
        if isinstance(v, pd.Series):
            return {str(key): fmt(value) for key, value in v.to_dict().items()}
        if isinstance(v, np.ndarray):
            return v.tolist()
        if isinstance(v, (np.integer, np.floating)):
            return v.item()
        if isinstance(v, (pd.Timestamp, Path)):
            return str(v)
        return v

    return fmt(summary)


def redact_summary(summary: dict, config) -> dict:
    return redact_summary_util(summary, config)

