from __future__ import annotations

from typing import Any, Tuple


def _ensure_batch(batch: Any) -> list:
    return batch if isinstance(batch, list) else []


def generic_expectations(name: str, summary: dict, batch: Any, *args) -> Tuple[str, dict, Any]:
    expectations = _ensure_batch(batch)
    expectations.append({"column": name, "expectation": "exist"})
    if summary.get("n_missing", 0) == 0:
        expectations.append({"column": name, "expectation": "not_null"})
    if summary.get("is_unique"):
        expectations.append({"column": name, "expectation": "unique"})
    return name, summary, expectations


def numeric_expectations(name: str, summary: dict, batch: Any, *args) -> Tuple[str, dict, Any]:
    name, summary, expectations = generic_expectations(name, summary, batch, *args)
    expectations.append({"column": name, "expectation": "numeric"})
    if summary.get("min") is not None and summary.get("max") is not None:
        expectations.append({"column": name, "expectation": "between", "min": summary.get("min"), "max": summary.get("max")})
    return name, summary, expectations


def categorical_expectations(name: str, summary: dict, batch: Any, *args) -> Tuple[str, dict, Any]:
    name, summary, expectations = generic_expectations(name, summary, batch, *args)
    if summary.get("n_distinct", 0) <= 10 or summary.get("p_distinct", 1.0) <= 0.2:
        expectations.append({"column": name, "expectation": "in_set", "values": list(getattr(summary.get("value_counts_without_nan"), "index", []))})
    return name, summary, expectations


def datetime_expectations(name: str, summary: dict, batch: Any, *args) -> Tuple[str, dict, Any]:
    name, summary, expectations = generic_expectations(name, summary, batch, *args)
    expectations.append({"column": name, "expectation": "datetime"})
    return name, summary, expectations


def path_expectations(name: str, summary: dict, batch: Any, *args) -> Tuple[str, dict, Any]:
    return generic_expectations(name, summary, batch, *args)


def image_expectations(name: str, summary: dict, batch: Any, *args) -> Tuple[str, dict, Any]:
    return generic_expectations(name, summary, batch, *args)


def url_expectations(name: str, summary: dict, batch: Any, *args) -> Tuple[str, dict, Any]:
    return generic_expectations(name, summary, batch, *args)


def file_expectations(name: str, summary: dict, batch: Any, *args) -> Tuple[str, dict, Any]:
    return generic_expectations(name, summary, batch, *args)

