from __future__ import annotations

from itertools import combinations
from typing import Any, List, Tuple

import pandas as pd

from ydata_profiling.visualisation.plot import scatter_pairwise


def get_scatter_tasks(config, continuous_variables: list) -> List[Tuple[Any, Any]]:
    targets = list(config.interactions.targets or [])
    if targets:
        return [(target, other) for target in targets for other in continuous_variables if target != other]
    return list(combinations(continuous_variables, 2))


def get_scatter_plot(config, df: pd.DataFrame, x: Any, y: Any, continuous_variables: list) -> str:
    if x not in df.columns or y not in df.columns:
        return ""
    return scatter_pairwise(config, df[x], df[y], x_label=str(x), y_label=str(y))

