from __future__ import annotations

import warnings
from typing import Dict, List, Optional, Sized

import pandas as pd

from ydata_profiling.config import Settings

CORRELATION_PEARSON = "pearson"
CORRELATION_SPEARMAN = "spearman"


class CorrelationBackend:
    """Helper class to select and cache the appropriate correlation backend."""

    def __init__(self, df: Sized):
        self.df = df
        self.use_spark = df.__class__.__module__.startswith("pyspark")

    def get_method(self, method_name: str):
        if self.use_spark:
            from ydata_profiling.model.spark import (
                auto_compute,
                cramers_compute,
                kendall_compute,
                pearson_compute,
                phik_compute,
                spearman_compute,
            )
        else:
            from ydata_profiling.model.pandas import (
                auto_compute,
                cramers_compute,
                kendall_compute,
                pearson_compute,
                phik_compute,
                spearman_compute,
            )
        return {
            "auto_compute": auto_compute,
            "spearman_compute": spearman_compute,
            "pearson_compute": pearson_compute,
            "kendall_compute": kendall_compute,
            "cramers_compute": cramers_compute,
            "phik_compute": phik_compute,
        }[method_name]


class Correlation:
    _method_name: str = ""

    def compute(self, config: Settings, df: Sized, summary: dict, backend: CorrelationBackend) -> Optional[Sized]:
        return backend.get_method(self._method_name)(config, df, summary)


class Auto(Correlation):
    _method_name = "auto_compute"


class Spearman(Correlation):
    _method_name = "spearman_compute"


class Pearson(Correlation):
    _method_name = "pearson_compute"


class Kendall(Correlation):
    _method_name = "kendall_compute"


class Cramers(Correlation):
    _method_name = "cramers_compute"


class PhiK(Correlation):
    _method_name = "phik_compute"


def warn_correlation(correlation_name: str, error: str) -> None:
    warnings.warn(
        f"Could not calculate correlation '{correlation_name}': {error}. "
        f"Disable it with correlations.{{'{correlation_name}': {{'calculate': False}}}}."
    )


def calculate_correlation(config: Settings, df: Sized, correlation_name: str, summary: dict) -> Optional[Sized]:
    backend = CorrelationBackend(df)
    strategy = {
        "auto": Auto(),
        "pearson": Pearson(),
        "spearman": Spearman(),
        "kendall": Kendall(),
        "cramers": Cramers(),
        "phi_k": PhiK(),
    }[correlation_name]
    try:
        return strategy.compute(config, df, summary, backend)
    except Exception as exc:
        warn_correlation(correlation_name, str(exc))
        return None


def perform_check_correlation(correlation_matrix: pd.DataFrame, threshold: float) -> Dict[str, List[str]]:
    results: Dict[str, List[str]] = {}
    if correlation_matrix is None or correlation_matrix.empty:
        return results
    for row in correlation_matrix.index:
        correlated = []
        for column in correlation_matrix.columns:
            if row == column:
                continue
            value = correlation_matrix.loc[row, column]
            if pd.notna(value) and abs(float(value)) >= threshold:
                correlated.append(str(column))
        if correlated:
            results[str(row)] = correlated
    return results


def get_active_correlations(config: Settings) -> List[str]:
    return [name for name, corr in config.correlations.items() if corr.calculate]

