from typing import Any, Callable, Dict, Optional, Sized

import pandas as pd

from ydata_profiling.config import Settings


class MissingDataBackend:
    """Helper class to select and cache the appropriate missing-data backend."""

    def __init__(self, df: Sized):
        self.use_spark = df.__class__.__module__.startswith("pyspark")

    def get_method(self, method_name: str) -> Callable:
        if self.use_spark:
            from ydata_profiling.model.spark import missing_bar, missing_heatmap, missing_matrix
        else:
            from ydata_profiling.model.pandas import missing_bar, missing_heatmap, missing_matrix
        return {
            "missing_bar": missing_bar,
            "missing_matrix": missing_matrix,
            "missing_heatmap": missing_heatmap,
        }[method_name]


class MissingData:
    _method_name: str = ""

    def compute(self, config: Settings, df: Sized, backend: MissingDataBackend) -> Optional[Sized]:
        return backend.get_method(self._method_name)(config, df)


class MissingBar(MissingData):
    _method_name = "missing_bar"


class MissingMatrix(MissingData):
    _method_name = "missing_matrix"


class MissingHeatmap(MissingData):
    _method_name = "missing_heatmap"


def get_missing_active(config: Settings, table_stats: dict) -> Dict[str, Any]:
    settings = {}
    if table_stats.get("n_cells_missing", 0) == 0:
        return settings
    mapping = {
        "bar": MissingBar(),
        "matrix": MissingMatrix(),
        "heatmap": MissingHeatmap(),
    }
    for name, active in config.missing_diagrams.items():
        if active and name in mapping:
            settings[name] = {
                "name": name,
                "caption": f"Missing data {name}",
                "function": mapping[name],
            }
    return settings


def get_missing_diagram(config: Settings, df: pd.DataFrame, settings: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    backend = MissingDataBackend(df)
    image = settings["function"].compute(config, df, backend)
    if not image:
        return None
    return {
        "name": settings["name"],
        "caption": settings["caption"],
        "image": image,
    }

