@dataclass
class Alert:
    alert_type: AlertType
    values: Optional[Dict] = None
    column_name: Optional[str] = None
    fields: Optional[Set] = None
    is_empty: bool = False
    _anchor_id: Optional[str] = None

    @property
    def alert_type_name(self) -> str:
        return self.alert_type.name.lower()

    @property
    def anchor_id(self) -> Optional[str]:
        if self._anchor_id:
            return self._anchor_id
        if self.column_name:
            return slugify(f"{self.column_name}-{self.alert_type_name}")
        return None

    def _get_description(self) -> str:
        descriptions = {
            AlertType.CONSTANT: "This variable has a constant value.",
            AlertType.ZEROS: "This variable contains zeros.",
            AlertType.HIGH_CORRELATION: "This variable is highly correlated.",
            AlertType.HIGH_CARDINALITY: "This variable has a high cardinality.",
            AlertType.UNSUPPORTED: "This variable is unsupported.",
            AlertType.DUPLICATES: "This variable contains duplicates.",
            AlertType.NEAR_DUPLICATES: "This variable contains duplicates.",
            AlertType.SKEWED: "This variable is highly skewed.",
            AlertType.IMBALANCE: "This variable is imbalanced.",
            AlertType.MISSING: "This variable contains missing values.",
            AlertType.INFINITE: "This variable contains infinite values.",
            AlertType.TYPE_DATE: "This variable is likely a datetime, but treated as categorical.",
            AlertType.UNIQUE: "This variable has unique values.",
            AlertType.DIRTY_CATEGORY: "This variable has potential fuzzy categories.",
            AlertType.CONSTANT_LENGTH: "This variable has a constant length.",
            AlertType.REJECTED: "Variables are rejected if we do not want to consider them for further analysis.",
            AlertType.UNIFORM: "The variable is uniformly distributed.",
            AlertType.NON_STATIONARY: "The variable is a non-stationary series.",
            AlertType.SEASONAL: "The variable is a seasonal time series.",
            AlertType.EMPTY: "The DataFrame is empty.",
        }
        return descriptions[self.alert_type]

    def fmt(self) -> str:
        target = f" [{self.column_name}]" if self.column_name else ""
        return f"{self._get_description()}{target}"

