    def __init__(self, values: Optional[Dict] = None, column_name: Optional[str] = None, is_empty: bool = False):
        super().__init__(AlertType.UNIFORM, values, column_name, is_empty=is_empty)


class UniqueAlert(Alert):
    def __init__(self, values: Optional[Dict] = None, column_name: Optional[str] = None, is_empty: bool = False):
        super().__init__(AlertType.UNIQUE, values, column_name, is_empty=is_empty)


class UnsupportedAlert(Alert):
    def __init__(self, values: Optional[Dict] = None, column_name: Optional[str] = None, is_empty: bool = False):
        super().__init__(AlertType.UNSUPPORTED, values, column_name, is_empty=is_empty)


class ZerosAlert(Alert):
    def __init__(self, values: Optional[Dict] = None, column_name: Optional[str] = None, is_empty: bool = False):
        super().__init__(AlertType.ZEROS, values, column_name, is_empty=is_empty)


class RejectedAlert(Alert):
    def __init__(self, values: Optional[Dict] = None, column_name: Optional[str] = None, is_empty: bool = False):
        super().__init__(AlertType.REJECTED, values, column_name, is_empty=is_empty)


def alert_value(value: float) -> bool:
    return bool(value and value > 0)


def skewness_alert(v: float, threshold: int) -> bool:
    return pd.notna(v) and abs(float(v)) > threshold


def type_date_alert(series: pd.Series) -> bool:
    parsed = pd.to_datetime(series, errors="coerce")
    return parsed.notna().mean() > 0.8


def generic_alerts(summary: dict) -> List[Alert]:
    alerts: List[Alert] = []
    if summary.get("p_missing", 0) > 0:
        alerts.append(MissingAlert())
    if summary.get("n_distinct") == 1 and summary.get("n", 0) > 0:
        alerts.append(ConstantAlert())
    if summary.get("is_unique"):
        alerts.append(UniqueAlert())
    return alerts


def supported_alerts(summary: dict) -> List[Alert]:
    alerts: List[Alert] = []
    if summary.get("hashable", True) is False:
        alerts.append(RejectedAlert())
    return alerts


def unsupported_alerts() -> List[Alert]:
    return [UnsupportedAlert()]


def categorical_alerts(config, summary: dict) -> List[Alert]:
    alerts: List[Alert] = []
    if summary.get("n_distinct", 0) > config.vars.cat.cardinality_threshold:
        alerts.append(HighCardinalityAlert())
    if summary.get("imbalance", 0) > config.vars.cat.imbalance_threshold:
        alerts.append(ImbalanceAlert())
    if summary.get("max_length") == summary.get("min_length") and summary.get("n", 0) > 0:
        alerts.append(ConstantLengthAlert())
    if config.vars.cat.dirty_categories and summary.get("dirty_categories"):
        alerts.append(DirtyCategoryAlert())
    if "first_rows" in summary and isinstance(summary["first_rows"], pd.Series) and type_date_alert(summary["first_rows"]):
        alerts.append(TypeDateAlert())
    return alerts


def boolean_alerts(config, summary: dict) -> List[Alert]:
    alerts: List[Alert] = []
    if summary.get("imbalance", 0) > config.vars.bool.imbalance_threshold:
        alerts.append(ImbalanceAlert())
    return alerts


def numeric_alerts(config, summary: dict) -> List[Alert]:
    alerts: List[Alert] = []
    if alert_value(summary.get("p_zeros", 0)):
        alerts.append(ZerosAlert())
    if skewness_alert(summary.get("skewness", 0), config.vars.num.skewness_threshold):
        alerts.append(SkewedAlert())
    if summary.get("n_infinite", 0) > 0:
        alerts.append(InfiniteAlert())
    histogram = summary.get("histogram", {}).get("counts") if isinstance(summary.get("histogram"), dict) else None
    if histogram is not None and len(histogram) > 1 and pd.Series(histogram).std() < 1e-9:
        alerts.append(UniformAlert())
    return alerts


def timeseries_alerts(config, summary: dict) -> List[Alert]:
    alerts: List[Alert] = []
    if summary.get("stationary") is False:
        alerts.append(NonStationaryAlert())
    if summary.get("seasonality_presence"):
        alerts.append(SeasonalAlert())
    return alerts


def check_variable_alerts(config, col: str, description: dict) -> List[Alert]:
    alerts: List[Alert] = []
    alerts.extend(generic_alerts(description))
    dtype = description.get("type")
    if dtype == "Unsupported":
        alerts.extend(unsupported_alerts())
    else:
        alerts.extend(supported_alerts(description))
        if dtype == "Categorical":
            alerts.extend(categorical_alerts(config, description))
        elif dtype == "Text":
            alerts.extend(categorical_alerts(config, description))
        elif dtype == "Numeric":
            alerts.extend(numeric_alerts(config, description))
        elif dtype == "TimeSeries":
            alerts.extend(numeric_alerts(config, description))
            alerts.extend(timeseries_alerts(config, description))
        elif dtype == "Boolean":
            alerts.extend(boolean_alerts(config, description))
    for alert in alerts:
        alert.column_name = col
        alert.values = description
    return alerts


def check_table_alerts(table: dict) -> List[Alert]:
    alerts: List[Alert] = []
    if table.get("n", 0) == 0:
        alerts.append(EmptyAlert())
    if table.get("n_duplicates", 0) > 0:
        alerts.append(DuplicatesAlert(values=table))
    return alerts


def check_correlation_alerts(config, correlations: dict) -> List[Alert]:
    from ydata_profiling.model.correlations import perform_check_correlation

    alerts: List[Alert] = []
    for name, matrix in correlations.items():
        corr_cfg = config.correlations.get(name)
        threshold = getattr(corr_cfg, "threshold", 0.5) if corr_cfg else 0.5
        for column, related in perform_check_correlation(matrix, threshold).items():
            if related:
                alerts.append(HighCorrelationAlert(values={"related": related}, column_name=column))
    return alerts


def get_alerts(config, table_stats: dict, series_description: dict, correlations: dict) -> List[Alert]:
    alerts = check_table_alerts(table_stats)
    for col, description in series_description.items():
        alerts.extend(check_variable_alerts(config, col, description))
    alerts.extend(check_correlation_alerts(config, correlations))
    return sorted(alerts, key=lambda alert: (alert.alert_type_name, alert.column_name or ""))

