from __future__ import annotations

import functools
from typing import Any, Callable, Dict, Optional, Tuple

import numpy as np
import pandas as pd
from multimethod import multimethod
from scipy import stats


def func_nullable_series_contains(fn: Callable) -> Callable:
    """Decorator for nullable series."""

    @functools.wraps(fn)
    def inner(config, series: pd.Series, state: dict, *args, **kwargs) -> bool:
        if getattr(series, "empty", False):
            return False
        cleaned = series.dropna() if hasattr(series, "dropna") else series
        if getattr(cleaned, "empty", False):
            return False
        return fn(config, cleaned, state, *args, **kwargs)

    return inner


def series_hashable(
    fn: Callable[[Any, pd.Series, dict], Tuple[Any, pd.Series, dict]]
) -> Callable[[Any, pd.Series, dict], Tuple[Any, pd.Series, dict]]:
    """Decorator that checks if series values are hashable before processing."""

    @functools.wraps(fn)
    def inner(config, series: pd.Series, summary: dict):
        if not summary.get("hashable", True):
            return config, series, summary
        return fn(config, series, summary)

    return inner


def series_handle_nulls(
    fn: Callable[[Any, pd.Series, dict], Tuple[Any, pd.Series, dict]]
) -> Callable[[Any, pd.Series, dict], Tuple[Any, pd.Series, dict]]:
    """Decorator that handles null values in series before processing."""

    @functools.wraps(fn)
    def inner(config, series: pd.Series, summary: dict):
        cleaned = series.dropna() if getattr(series, "hasnans", False) else series
        return fn(config, cleaned, summary)

    return inner


def named_aggregate_summary(series: pd.Series, key: str) -> dict:
    return {
        f"max_{key}": np.max(series) if len(series) else np.nan,
        f"mean_{key}": np.mean(series) if len(series) else np.nan,
        f"median_{key}": np.median(series) if len(series) else np.nan,
        f"min_{key}": np.min(series) if len(series) else np.nan,
    }


def chi_square(values: Optional[np.ndarray] = None, histogram: Optional[np.ndarray] = None) -> dict:
    if histogram is None:
        values = np.asarray(values if values is not None else [])
        if values.size == 0:
            return {"statistic": 0.0, "pvalue": 0.0}
        bins = np.histogram_bin_edges(values, bins="auto")
        histogram, _ = np.histogram(values, bins=bins)
    histogram = np.asarray(histogram)
    if histogram.size == 0 or histogram.sum() == 0:
        return {"statistic": 0.0, "pvalue": 0.0}
    statistic, pvalue = stats.chisquare(histogram)
    return {"statistic": float(statistic), "pvalue": float(pvalue)}


def mad(arr: np.ndarray) -> np.ndarray:
    arr = np.asarray(arr)
    if arr.size == 0:
        return np.nan
    med = np.median(arr)
    return np.median(np.abs(arr - med))


def numeric_stats_pandas(series: pd.Series) -> Dict[str, Any]:
    if len(series) == 0:
        return {key: np.nan for key in ["mean", "std", "variance", "min", "max", "kurtosis", "skewness", "sum"]}
    return {
        "mean": float(series.mean()),
        "std": float(series.std()),
        "variance": float(series.var()),
        "min": float(series.min()),
        "max": float(series.max()),
        "kurtosis": float(series.kurt()),
        "skewness": float(series.skew()),
        "sum": float(series.sum()),
    }


def numeric_stats_numpy(
    present_values: np.ndarray, series: pd.Series, series_description: Dict[str, Any]
) -> Dict[str, Any]:
    if len(present_values) == 0:
        return {key: np.nan for key in ["mean", "std", "variance", "min", "max", "kurtosis", "skewness", "sum"]}
    stats_dict = numeric_stats_pandas(pd.Series(present_values))
    return stats_dict


def histogram_compute(
    config,
    finite_values: np.ndarray,
    n_unique: int,
    name: str = "histogram",
    weights: Optional[np.ndarray] = None,
) -> dict:
    values = np.asarray(finite_values, dtype=float)
    if values.size == 0:
        return {name: {"counts": np.array([]), "bins": np.array([])}}
    bins_setting = getattr(config.plot.histogram, "bins", 50)
    bins = bins_setting if bins_setting > 0 else min(max(n_unique, 1), getattr(config.plot.histogram, "max_bins", 250))
    counts, edges = np.histogram(values, bins=bins, weights=weights)
    return {name: {"counts": counts, "bins": edges}}


