from __future__ import annotations

import functools
from typing import Callable, Dict

import pandas as pd


def is_nullable(series: pd.Series, state: dict) -> bool:
    return series.count() > 0


def try_func(fn: Callable) -> Callable:
    @functools.wraps(fn)
    def inner(series: pd.Series, *args, **kwargs) -> bool:
        try:
            return fn(series, *args, **kwargs)
        except Exception:
            return False

    return inner


def series_handle_nulls(fn: Callable) -> Callable:
    @functools.wraps(fn)
    def inner(series: pd.Series, *args, **kwargs):
        cleaned = series.dropna() if getattr(series, "hasnans", False) else series
        return fn(cleaned, *args, **kwargs)

    return inner


def string_is_bool(series: pd.Series, state: dict, k: Dict[str, bool]) -> bool:
    @series_handle_nulls
    @try_func
    def tester(s: pd.Series, state: dict) -> bool:
        lowered = s.astype(str).str.lower().str.strip()
        return lowered.isin(list(k.keys())).all()

    return tester(series, state)


def string_to_bool(series: pd.Series, state: dict, k: Dict[str, bool]) -> pd.Series:
    lowered = series.astype(str).str.lower().str.strip()
    mapped = lowered.map(k)
    if mapped.isna().any():
        return mapped.astype("boolean")
    return mapped.astype(bool)


def numeric_is_category(series: pd.Series, state: dict, k) -> bool:
    n_unique = series.nunique(dropna=True)
    threshold = getattr(k.vars.num, "low_categorical_threshold", 5)
    return 1 <= n_unique <= threshold


def to_category(series: pd.Series, state: dict) -> pd.Series:
    return series.astype("string")


@series_handle_nulls
def series_is_string(series: pd.Series, state: dict) -> bool:
    return series.map(lambda value: isinstance(value, str)).all()


@series_handle_nulls
def string_is_category(series: pd.Series, state: dict, k) -> bool:
    distinct = series.nunique(dropna=True)
    total = len(series)
    return (
        distinct >= 1
        and distinct <= k.vars.cat.cardinality_threshold
        and (distinct / max(total, 1)) <= k.vars.cat.percentage_cat_threshold
        and not string_is_bool(series, state, k.vars.bool.mappings)
    )


@series_handle_nulls
def string_is_datetime(series: pd.Series, state: dict) -> bool:
    parsed = pd.to_datetime(series, errors="coerce")
    return parsed.notna().any()


@series_handle_nulls
def string_is_numeric(series: pd.Series, state: dict, k) -> bool:
    parsed = pd.to_numeric(series, errors="coerce")
    return parsed.notna().all() and not string_is_category(series, state, k)


def string_to_datetime(series: pd.Series, state: dict) -> pd.Series:
    return pd.to_datetime(series, errors="coerce")


def string_to_numeric(series: pd.Series, state: dict) -> pd.Series:
    return pd.to_numeric(series, errors="coerce")


def to_bool(series: pd.Series) -> pd.Series:
    if getattr(series, "hasnans", False):
        return series.astype("boolean")
    return series.astype(bool)


@series_handle_nulls
def object_is_bool(series: pd.Series, state: dict) -> bool:
    return series.map(lambda value: isinstance(value, bool)).all()

