from __future__ import annotations

import re
from pathlib import Path
from typing import Dict, Optional, Set
from urllib.parse import urlparse

import pandas as pd
from visions import StandardSet, VisionsTypeset


class Boolean:
    pass


class Numeric:
    pass


class Complex:
    pass


class Text:
    pass


class DateTime:
    pass


class Categorical:
    pass


class URL:
    pass


class PathType:
    pass


class File:
    pass


class Image:
    pass


class Unsupported:
    pass


class TimeSeries:
    pass


def typeset_types(config) -> Set[type]:
    """Define types based on the config."""

    return {
        Boolean,
        Numeric,
        Complex,
        Text,
        DateTime,
        Categorical,
        URL,
        PathType,
        File,
        Image,
        Unsupported,
        TimeSeries,
    }


class ProfilingTypeSet(StandardSet):
    def __init__(self, config, type_schema: dict = None):
        super().__init__()
        self.config = config
        self.type_schema = self._init_type_schema(type_schema)
        self._mapping: Dict[str, type] = {
            "Boolean": Boolean,
            "Numeric": Numeric,
            "Complex": Complex,
            "Text": Text,
            "DateTime": DateTime,
            "Categorical": Categorical,
            "URL": URL,
            "Path": PathType,
            "File": File,
            "Image": Image,
            "Unsupported": Unsupported,
            "TimeSeries": TimeSeries,
        }

    def _init_type_schema(self, type_schema: dict) -> dict:
        return type_schema or {}

    def _get_type(self, type_name: str):
        return self._mapping[type_name]

    def detect_type(self, series: pd.Series):
        name = str(series.name)
        if name in self.type_schema:
            target = self.type_schema[name]
            if isinstance(target, str):
                return self._get_type(target)
            return target
        return self._infer_type(series)

    infer_type = detect_type

    def _infer_type(self, series: pd.Series):
        non_null = series.dropna()
        if self.config.vars.timeseries.active and pd.api.types.is_numeric_dtype(series):
            return TimeSeries
        if pd.api.types.is_bool_dtype(series):
            return Boolean
        if pd.api.types.is_complex_dtype(series):
            return Complex
        if pd.api.types.is_numeric_dtype(series):
            return Numeric
        if pd.api.types.is_datetime64_any_dtype(series):
            return DateTime
        if non_null.empty:
            return Unsupported
        if all(isinstance(value, (str, Path)) for value in non_null.head(20)):
            as_str = non_null.astype(str)
            if self.config.vars.image.active and as_str.map(_path_is_image).all():
                return Image
            if self.config.vars.file.active and as_str.map(lambda value: Path(value).exists() and Path(value).is_file()).all():
                return File
            if self.config.vars.path.active and as_str.map(_looks_like_path).all():
                return PathType
            if self.config.vars.url.active and as_str.map(_looks_like_url).all():
                return URL
            if _looks_like_datetime(as_str):
                return DateTime
            if _is_categorical(as_str, self.config):
                return Categorical
            return Text
        return Unsupported


def _looks_like_url(value: str) -> bool:
    parsed = urlparse(value)
    return bool(parsed.scheme and parsed.netloc)


def _looks_like_path(value: str) -> bool:
    return bool(re.search(r"[\\/]", value)) or Path(value).suffix != ""


def _path_is_image(value: str) -> bool:
    return Path(value).suffix.lower() in {".png", ".jpg", ".jpeg", ".gif", ".bmp", ".tiff", ".webp"}


def _looks_like_datetime(series: pd.Series) -> bool:
    parsed = pd.to_datetime(series, errors="coerce")
    return parsed.notna().mean() > 0.8


def _is_categorical(series: pd.Series, config) -> bool:
    distinct = series.nunique(dropna=True)
    total = len(series)
    return (
        distinct <= config.vars.cat.cardinality_threshold
        and (distinct / max(total, 1)) <= config.vars.cat.percentage_cat_threshold
    )

