    try:
        value_counts_with_nan = series.value_counts(dropna=False)
        value_counts_without_nan = series.dropna().value_counts()
    except Exception:
        hashable = False
        value_counts_with_nan = pd.Series(dtype="int64")
        value_counts_without_nan = pd.Series(dtype="int64")

    orderable = True
    try:
        series.dropna().sort_values()
    except Exception:
        orderable = False

    n_missing = int(series.isna().sum())
    n = int(series.count())
    summary.update(
        {
            "n": n,
            "count": n,
            "n_missing": n_missing,
            "p_missing": n_missing / max(len(series), 1),
            "value_counts_with_nan": value_counts_with_nan,
            "value_counts_without_nan": value_counts_without_nan,
            "hashable": hashable,
            "orderable": orderable,
        }
