def counter_to_series(counter: Counter) -> pd.Series:
    if not counter:
        return pd.Series(dtype="int64")
    items, counts = zip(*counter.most_common())
    return pd.Series(counts, index=list(items))


def unicode_summary_vc(vc: pd.Series) -> dict:
    character_counts = get_character_counts_vc(vc)
    try:
        import unicodedata

        categories = Counter()
        for char, count in character_counts.items():
            categories[unicodedata.category(char)] += int(count)
        category_alias_counts = counter_to_series(categories)
    except Exception:
        category_alias_counts = pd.Series(dtype="int64")
    return {
        "n_characters_distinct": int(len(character_counts)),
        "n_characters": int(character_counts.sum()) if len(character_counts) else 0,
        "character_counts": character_counts,
        "category_alias_counts": category_alias_counts,
        "script_counts": pd.Series(dtype="int64"),
        "block_alias_counts": pd.Series(dtype="int64"),
    }


