def pandas_describe_timeseries_1d(config: Settings, series: pd.Series, summary: dict):
    values = pd.to_numeric(series, errors="coerce")
    stationary, pvalue = stationarity_test(config, values)
    seasonality = seasonality_test(values)
    summary.update(
        {
            "stationary": stationary,
            "stationarity_pvalue": pvalue,
            "seasonality_presence": seasonality["seasonality_presence"],
            "seasonalities": seasonality["seasonalities"],
            "gap_stats": compute_gap_stats(series),
            "autocorrelation": float(values.autocorr()) if len(values.dropna()) > 1 else np.nan,
        }
    )
    return config, values, summary


