def path_summary(series: pd.Series) -> dict:
    paths = series.astype(str).map(Path)
    suffix_counts = paths.map(lambda p: p.suffix).value_counts()
    stem_counts = paths.map(lambda p: p.stem).value_counts()
    name_counts = paths.map(lambda p: p.name).value_counts()
    parent_counts = paths.map(lambda p: str(p.parent)).value_counts()
    anchor_counts = paths.map(lambda p: p.anchor).value_counts()
    common_prefix = os.path.commonprefix([str(path) for path in paths]) if len(paths) else ""
    return {
        "common_prefix": common_prefix,
        "suffix_counts": suffix_counts,
        "stem_counts": stem_counts,
        "name_counts": name_counts,
        "parent_counts": parent_counts,
        "anchor_counts": anchor_counts,
    }


