    existing = [path for path in paths if path.exists()]
    return {
        "file_size": pd.Series([path.stat().st_size for path in existing]).describe() if existing else pd.Series(dtype="float64"),
        "file_created_time": pd.Series([datetime.fromtimestamp(path.stat().st_ctime).strftime("%Y-%m-%d %H:%M:%S") for path in existing]),
        "file_accessed_time": pd.Series([datetime.fromtimestamp(path.stat().st_atime).strftime("%Y-%m-%d %H:%M:%S") for path in existing]),
        "file_modified_time": pd.Series([datetime.fromtimestamp(path.stat().st_mtime).strftime("%Y-%m-%d %H:%M:%S") for path in existing]),
    }


