def open_image(path: Path) -> Optional[PILImage.Image]:
    try:
        return PILImage.open(path)
    except Exception:
        return None


def is_image_truncated(image: PILImage.Image) -> bool:
    try:
        image.load()
        return False
    except Exception:
        return True


def get_image_shape(image: PILImage.Image) -> Optional[Tuple[int, int]]:
    try:
        return image.size
    except Exception:
        return None


def hash_image(image: PILImage.Image) -> Optional[str]:
    try:
        return str(imagehash.phash(image))
    except Exception:
        return None


def decode_byte_exif(exif_val: str | bytes) -> str:
    return exif_val.decode("utf-8", errors="ignore") if isinstance(exif_val, bytes) else str(exif_val)


def extract_exif(image: PILImage.Image) -> dict:
    try:
        raw = image.getexif() or {}
        return {str(key): decode_byte_exif(value) for key, value in raw.items()}
    except Exception:
        return {}


def path_is_image(p: Path) -> bool:
    return p.suffix.lower() in {".png", ".jpg", ".jpeg", ".gif", ".bmp", ".tiff", ".webp"}


def count_duplicate_hashes(image_descriptions: dict) -> int:
    hashes = [info.get("hash") for info in image_descriptions.values() if info.get("hash")]
    counts = Counter(hashes)
    return sum(count - 1 for count in counts.values() if count > 1)


def extract_exif_series(image_exifs: list) -> dict:
    key_counter = Counter()
    per_key = {}
    for exif in image_exifs:
        for key, value in exif.items():
            key_counter[key] += 1
            per_key.setdefault(key, Counter())[value] += 1
    return {
        "exif_keys": counter_to_series(key_counter),
        "exif_data": {key: counter_to_series(counter) for key, counter in per_key.items()},
    }


def extract_image_information(path: Path, exif: bool = False, hash: bool = False) -> dict:
    image = open_image(path)
    if image is None:
        return {}
    info = {
        "shape": get_image_shape(image),
        "truncated": is_image_truncated(image),
    }
    if exif:
        info["exif"] = extract_exif(image)
    if hash:
        info["hash"] = hash_image(image)
    return info


def image_summary(series: pd.Series, exif: bool = False, hash: bool = False) -> dict:
    descriptions = {
        str(path): extract_image_information(Path(path), exif=exif, hash=hash)
        for path in series.astype(str)
        if Path(path).exists()
    }
    shapes = pd.Series([info["shape"] for info in descriptions.values() if info.get("shape")], dtype="object")
    exifs = [info.get("exif", {}) for info in descriptions.values()]
    return {
        "image_dimensions": shapes,
        "n_truncated_images": int(sum(1 for info in descriptions.values() if info.get("truncated"))),
        "n_duplicate_hashes": count_duplicate_hashes(descriptions) if hash else 0,
        **extract_exif_series(exifs) if exif else {},
    }


@describe_image_1d.register
def pandas_describe_image_1d(config: Settings, series: pd.Series, summary: dict):
    summary.update(image_summary(series, exif=config.vars.image.exif, hash=config.vars.image.hash))
    return config, series.astype(str), summary


def _is_cast_type_defined(typeset, variable: str) -> bool:
    return variable in getattr(typeset, "type_schema", {})


def pandas_get_series_descriptions(config: Settings, df: pd.DataFrame, summarizer, typeset, pbar) -> dict:
    descriptions = {}
    for name, series in df.items():
        pbar.set_postfix_str(f"Describe variable: {name}")
        descriptions[str(name)] = pandas_describe_1d(config, series, summarizer, typeset)
        pbar.update()
    return sort_column_names(descriptions, config.sort)


@get_duplicates.register
def pandas_get_duplicates(config: Settings, df: pd.DataFrame, supported_columns: list):
    if not config.duplicates or not supported_columns:
        return {"n_duplicates": 0, "p_duplicates": 0.0}, None
    duplicated = int(df.duplicated(subset=supported_columns).sum())
    grouped = (
        df.groupby(supported_columns, dropna=False)
        .size()
        .reset_index(name=config.duplicates.key)
        .sort_values(config.duplicates.key, ascending=False)
    )
    grouped = grouped[grouped[config.duplicates.key] > 1].head(config.duplicates.head)
    return {"n_duplicates": duplicated, "p_duplicates": duplicated / max(len(df), 1)}, grouped if not grouped.empty else None


@get_sample.register
def pandas_get_sample(config: Settings, df: pd.DataFrame) -> List[Sample]:
    if not config.samples:
        return []
    samples: List[Sample] = []
    if config.samples.head:
        samples.append(Sample(name="Head", data=df.head(config.samples.head), caption="First rows"))
    if config.samples.tail:
        samples.append(Sample(name="Tail", data=df.tail(config.samples.tail), caption="Last rows"))
    if config.samples.random:
        samples.append(Sample(name="Random", data=df.sample(min(config.samples.random, len(df)), random_state=42), caption="Random sample"))
    return samples


@get_table_stats.register
def pandas_get_table_stats(config: Settings, df: pd.DataFrame, variable_stats: dict) -> dict:
    n = len(df)
    n_var = len(df.columns)
    n_cells_missing = int(df.isna().sum().sum())
    memory_size = int(df.memory_usage(index=True, deep=config.memory_deep).sum())
    types = Counter(info.get("type", "Unsupported") for info in variable_stats.values())
    return {
        "n": n,
        "n_var": n_var,
        "n_cells_missing": n_cells_missing,
        "p_cells_missing": n_cells_missing / max(n * max(n_var, 1), 1),
        "memory_size": memory_size,
        "record_size": memory_size / max(n, 1),
        "types": dict(types),
    }


@get_time_index_description.register
def pandas_get_time_index_description(config: Settings, df: pd.DataFrame, table_stats: dict) -> dict:
    if not config.vars.timeseries.active:
        return {}
    index = df.index
    if isinstance(index, pd.RangeIndex):
        return {}
    start = index.min()
    end = index.max()
    frequency = getattr(index, "inferred_freq", None) if isinstance(index, pd.DatetimeIndex) else None
    period = (end - start) / max(len(index) - 1, 1) if len(index) else 0
    return {
        "n_series": 1,
        "length": len(index),
        "start": start,
        "end": end,
        "period": period,
        "frequency": frequency,
    }


def _numeric_df(df: pd.DataFrame, summary: dict) -> pd.DataFrame:
    numeric = [column for column, info in summary.items() if info.get("type") in {"Numeric", "TimeSeries"}]
    return df[numeric].apply(pd.to_numeric, errors="coerce") if numeric else pd.DataFrame(index=df.index)


def _pairwise_spearman(col_1: pd.Series, col_2: pd.Series) -> float:
    return float(col_1.corr(col_2, method="spearman"))


def _cramers_corrected_stat(confusion_matrix: pd.DataFrame, correction: bool) -> float:
    if confusion_matrix.empty:
        return 0.0
    chi2 = stats.chi2_contingency(confusion_matrix, correction=correction)[0]
    n = confusion_matrix.to_numpy().sum()
    if n == 0:
        return 0.0
    phi2 = chi2 / n
    r, k = confusion_matrix.shape
    phi2corr = max(0.0, phi2 - (((k - 1) * (r - 1)) / max(n - 1, 1)))
    rcorr = r - (((r - 1) ** 2) / max(n - 1, 1))
    kcorr = k - (((k - 1) ** 2) / max(n - 1, 1))
    denom = min((kcorr - 1), (rcorr - 1))
    if denom <= 0:
        return 0.0
    return float(np.sqrt(phi2corr / denom))


def _pairwise_cramers(col_1: pd.Series, col_2: pd.Series) -> float:
    confusion = pd.crosstab(col_1, col_2)
    return _cramers_corrected_stat(confusion, correction=True)


def pearson_compute(config: Settings, df: pd.DataFrame, summary: dict) -> Optional[pd.DataFrame]:
    numeric_df = _numeric_df(df, summary)
    return None if numeric_df.empty else numeric_df.corr(method="pearson")


def spearman_compute(config: Settings, df: pd.DataFrame, summary: dict) -> Optional[pd.DataFrame]:
    numeric_df = _numeric_df(df, summary)
    return None if numeric_df.empty else numeric_df.corr(method="spearman")


def kendall_compute(config: Settings, df: pd.DataFrame, summary: dict) -> Optional[pd.DataFrame]:
    numeric_df = _numeric_df(df, summary)
    return None if numeric_df.empty else numeric_df.corr(method="kendall")


def cramers_compute(config: Settings, df: pd.DataFrame, summary: dict) -> Optional[pd.DataFrame]:
    categoricals = [column for column, info in summary.items() if info.get("type") in {"Categorical", "Boolean", "Text"}]
    if len(categoricals) < 2:
        return None
    matrix = pd.DataFrame(index=categoricals, columns=categoricals, dtype=float)
    for left in categoricals:
        for right in categoricals:
            matrix.loc[left, right] = 1.0 if left == right else _pairwise_cramers(df[left].astype(str), df[right].astype(str))
    return matrix


def phik_compute(config: Settings, df: pd.DataFrame, summary: dict) -> Optional[pd.DataFrame]:
    try:
        import phik  # noqa: F401

        usable = df[[column for column in df.columns if summary.get(column, {}).get("n_distinct", 0) <= config.categorical_maximum_correlation_distinct]].copy()
        if usable.empty:
            return None
        return usable.phik_matrix(interval_cols=[column for column, info in summary.items() if info.get("type") in {"Numeric", "TimeSeries"}])
    except Exception:
        numeric = pearson_compute(config, df, summary)
        if numeric is not None:
            return numeric
        return cramers_compute(config, df, summary)


def auto_compute(config: Settings, df: pd.DataFrame, summary: dict) -> Optional[pd.DataFrame]:
    numeric = pearson_compute(config, df, summary)
    if numeric is not None and not numeric.empty:
        return numeric
    return cramers_compute(config, df, summary)


