"""Formatters are mappings from object(s) to a string."""

from __future__ import annotations

import functools
import math
import re
from datetime import timedelta
from typing import Any, Callable, List, Optional, Union

import numpy as np


def list_args(func: Callable) -> Callable:
    """
    Extend the function to allow taking a list as the first argument, and apply the
    function on each of the elements.
    """

    @functools.wraps(func)
    def inner(arg: Any, *args: Any, **kwargs: Any) -> Any:
        if isinstance(arg, list):
            return [func(item, *args, **kwargs) for item in arg]
        return func(arg, *args, **kwargs)

    return inner


def remove_suffix(text: str, suffix: str) -> str:
    return text[: -len(suffix)] if suffix and text.endswith(suffix) else text


@list_args
def fmt_color(text: str, color: str) -> str:
    return f'<span style="color:{color}">{text}</span>'


@list_args
def fmt_class(text: str, cls: str) -> str:
    return f'<span class="{cls}">{text}</span>'


@list_args
def fmt_bytesize(num: float, suffix: str = "B") -> str:
    units = ["", "Ki", "Mi", "Gi", "Ti", "Pi"]
    value = float(num)
    for unit in units:
        if abs(value) < 1024.0:
            return f"{value:3.1f} {unit}{suffix}"
        value /= 1024.0
    return f"{value:.1f} Ei{suffix}"


@list_args
def fmt_percent(value: float, edge_cases: bool = True) -> str:
    if edge_cases and value is None:
        return "0.0%"
    return f"{100 * float(value):.1f}%"


@list_args
def fmt_timespan(num_seconds: Any, detailed: bool = False, max_units: int = 3) -> str:
    def round_number(count: Any, keep_width: bool = False) -> str:
        text = f"{float(count):.2f}"
        if keep_width:
            return text
        text = re.sub(r"0+$", "", text)
        return remove_suffix(text, ".")

    def coerce_seconds(value: Union[timedelta, int, float]) -> float:
        return value.total_seconds() if isinstance(value, timedelta) else float(value)

    def concatenate(items: List[str]) -> str:
        items = list(items)
        if not items:
            return ""
        if len(items) == 1:
            return items[0]
        return ", ".join(items[:-1]) + f" and {items[-1]}"

    def pluralize(count: Any, singular: str, plural: Optional[str] = None) -> str:
        plural = plural or singular + "s"
        word = singular if math.floor(float(count)) == 1 else plural
        return f"{round_number(count)} {word}"

    total_seconds = abs(coerce_seconds(num_seconds))
    units = [
        ("week", 604800),
        ("day", 86400),
        ("hour", 3600),
        ("minute", 60),
        ("second", 1),
    ]
    parts = []
    for name, factor in units:
        if total_seconds >= factor or (name == "second" and not parts):
            count = total_seconds / factor if factor == 1 and detailed else int(total_seconds // factor)
            if factor != 1:
                total_seconds %= factor
            parts.append(pluralize(count, name))
        if len(parts) >= max_units:
            break
    return concatenate(parts)


@list_args
def fmt_timespan_timedelta(delta: Any, detailed: bool = False, max_units: int = 3, precision: int = 10) -> str:
    if isinstance(delta, timedelta):
        return fmt_timespan(delta.total_seconds(), detailed=detailed, max_units=max_units)
    return fmt_timespan(delta, detailed=detailed, max_units=max_units)


@list_args
def fmt_numeric(value: float, precision: int = 10) -> str:
    text = f"{float(value):.{precision}g}"
    if "e+" in text or "e-" in text:
        base, exponent = text.split("e")
        exponent = exponent.lstrip("+")
        return f"{base} × 10<sup>{int(exponent)}</sup>"
    return text


@list_args
def fmt_number(value: int) -> str:
    return f"{int(value):n}"


@list_args
def fmt_array(value: np.ndarray, threshold: Any = np.nan) -> str:
    with np.printoptions(threshold=3 if np.isnan(threshold) else threshold):
        return np.array2string(np.asarray(value))


@list_args
def fmt_monotonic(value: int) -> str:
    mapping = {
        -2: "Strictly decreasing",
        -1: "Decreasing",
        0: "Not monotonic",
        1: "Increasing",
        2: "Strictly increasing",
    }
    if value not in mapping:
        raise ValueError("Monotonicity value must be between -2 and 2")
    return mapping[value]


@list_args
def fmt_badge(value: str) -> str:
    return re.sub(r"\(([^)]+)\)", r'<span class="badge bg-secondary">\1</span>', value)

