from __future__ import annotations

import base64
import io
from typing import Any, List, Optional, Tuple, Union

import matplotlib
import matplotlib.pyplot as plt
import numpy as np
import pandas as pd
import seaborn as sns
from matplotlib.colors import LinearSegmentedColormap
from matplotlib.dates import AutoDateLocator, ConciseDateFormatter
from statsmodels.graphics.tsaplots import plot_acf, plot_pacf
from wordcloud import WordCloud

from ydata_profiling.visualisation.context import manage_matplotlib_context
from ydata_profiling.visualisation.missing import get_font_size


def hex_to_rgb(value: str) -> Tuple[float, ...]:
    value = value.lstrip("#")
    return tuple(int(value[index : index + 2], 16) / 255.0 for index in (0, 2, 4))


def base64_image(image: bytes, mime_type: str) -> str:
    return f"data:{mime_type};base64,{base64.b64encode(image).decode('ascii')}"


def create_comparison_color_list(config) -> List[str]:
    colors = list(config.html.style.primary_colors)
    labels = list(getattr(config.html.style, "_labels", ["_"]))
    if len(colors) >= len(labels):
        return colors[: len(labels)]
    cmap = LinearSegmentedColormap.from_list("compare", colors, N=max(len(labels), 2))
    return [matplotlib.colors.to_hex(cmap(index / max(len(labels) - 1, 1))) for index in range(len(labels))]


def get_cmap_half(cmap) -> LinearSegmentedColormap:
    colors = cmap(np.linspace(0.5, 1.0, max(cmap.N // 2, 2)))
    return LinearSegmentedColormap.from_list(f"{cmap.name}_half", colors)


def get_correlation_font_size(n_labels: int) -> Optional[int]:
    if n_labels > 100:
        return 4
    if n_labels > 80:
        return 5
    if n_labels > 50:
        return 6
    if n_labels > 40:
        return 8
    return None


def _set_visibility(axis: matplotlib.axis.Axis, tick_mark: str = "none") -> matplotlib.axis.Axis:
    for side in ("top", "right", "bottom", "left"):
        axis.spines[side].set_visible(False)
    axis.xaxis.set_ticks_position(tick_mark)
    axis.yaxis.set_ticks_position(tick_mark)
    return axis


def _format_ts_date_axis(series: pd.Series, axis: matplotlib.axis.Axis):
    if isinstance(series.index, pd.DatetimeIndex):
        locator = AutoDateLocator()
        axis.xaxis.set_major_locator(locator)
        axis.xaxis.set_major_formatter(ConciseDateFormatter(locator))
    return axis


def _figure_to_base64(fig: plt.Figure, config, fmt: Optional[str] = None) -> str:
    buffer = io.BytesIO()
    fmt = fmt or config.plot.image_format.value
    if fmt == "svg":
        fig.savefig(buffer, format="svg", bbox_inches="tight")
        mime = "image/svg+xml"
    else:
        fig.savefig(buffer, format="png", bbox_inches="tight", dpi=getattr(config.plot, "dpi", 100))
        mime = "image/png"
    return base64_image(buffer.getvalue(), mime)


def format_fn(tick_val: int, tick_pos: Any) -> str:
    from ydata_profiling.utils.common import convert_timestamp_to_datetime

    return convert_timestamp_to_datetime(tick_val).strftime("%Y-%m-%d %H:%M:%S")


def make_autopct(values: pd.Series):
    def my_autopct(pct: float) -> str:
        total = values.sum()
        val = int(round(pct * total / 100.0))
        return f"{pct:.1f}% ({val:d})"

    return my_autopct


def _plot_word_cloud(config, series: Union[pd.Series, List[pd.Series]], figsize: tuple = (6, 4)) -> plt.Figure:
    entries = series if isinstance(series, list) else [series]
    fig, axes = plt.subplots(1, len(entries), figsize=(figsize[0] * len(entries), figsize[1]))
    axes = np.atleast_1d(axes)
    for axis, value in zip(axes, entries):
        frequencies = value.to_dict() if isinstance(value, pd.Series) else {}
        cloud = WordCloud(
            font_path=str(config.plot.font_path) if config.plot.font_path else None,
            background_color="white",
            random_state=123,
            width=300,
            height=200,
            scale=2,
        ).generate_from_frequencies(frequencies or {"empty": 1})
        axis.imshow(cloud, interpolation="bilinear")
        axis.axis("off")
    fig.tight_layout()
    return fig


def _plot_histogram(config, series: np.ndarray, bins: Union[int, np.ndarray], figsize: tuple = (6, 4), date: bool = False, hide_yaxis: bool = False) -> plt.Figure:
    fig, axis = plt.subplots(figsize=figsize)
    if isinstance(series, list):
        colors = create_comparison_color_list(config)
        for index, values in enumerate(series):
            axis.hist(values, bins=bins, alpha=0.5, color=colors[index % len(colors)])
    else:
        axis.hist(series, bins=bins, color=config.html.style.primary_color, alpha=0.8, density=config.plot.histogram.density)
    if date:
        for label in axis.get_xticklabels():
            label.set_rotation(45)
    if hide_yaxis:
        axis.get_yaxis().set_visible(False)
    fig.tight_layout()
    return fig


def _plot_pie_chart(data: pd.Series, colors: List, hide_legend: bool = False):
    fig, axis = plt.subplots(figsize=(6, 4))
    wedges, _, texts = axis.pie(data.values, colors=colors or None, autopct=make_autopct(data))
    legend = None if hide_legend else axis.legend(wedges, data.index, loc="center left", bbox_to_anchor=(1, 0.5))
    return axis, legend


def _plot_stacked_barh(data: pd.Series, colors: List, hide_legend: bool = False):
    fig, axis = plt.subplots(figsize=(6, 1.5))
    cumulative = 0
    total = data.sum()
    legend_handles = []
    for index, (label, value) in enumerate(data.items()):
        width = value / total if total else 0
        bar = axis.barh([0], [width], left=[cumulative], color=(colors[index] if colors else None), label=label)
        legend_handles.append(bar)
        cumulative += width
    axis.set_xlim(0, 1)
    axis.set_yticks([])
    legend = None if hide_legend else axis.legend(loc="center left", bbox_to_anchor=(1, 0.5))
    return axis, legend


def _prepare_heatmap_data(dataframe: pd.DataFrame, entity_column: str, sortby: Optional[Union[str, list]] = None, max_entities: int = 5, selected_entities: Optional[List[str]] = None) -> pd.DataFrame:
    frame = dataframe.copy()
    if sortby is not None:
        frame = frame.sort_values(sortby)
    if selected_entities is not None:
        frame = frame[frame[entity_column].isin(selected_entities)]
    return frame.head(max_entities).set_index(entity_column)


def _create_timeseries_heatmap(df: pd.DataFrame, figsize: Tuple[int, int] = (12, 5), color: str = "#337ab7") -> plt.Axes:
    fig, axis = plt.subplots(figsize=figsize)
    sns.heatmap(df, cmap=sns.light_palette(color, as_cmap=True), ax=axis)
    return axis


def _plot_timeseries(config, series: Union[list, pd.Series], figsize: tuple = (6, 4)) -> plt.Figure:
    fig, axis = plt.subplots(figsize=figsize)
    if isinstance(series, list):
        colors = create_comparison_color_list(config)
        for index, values in enumerate(series):
            axis.plot(values.index, values.values, color=colors[index % len(colors)], label=str(index))
