    return fig


def _get_ts_lag(config, series: pd.Series) -> int:
    lag = int(config.vars.timeseries.pacf_acf_lag)
    return int(np.min([lag, max((len(series) // 2) - 1, 1)]))


def _plot_acf_pacf(config, series: pd.Series, figsize: tuple = (15, 5)) -> str:
    fig, axes = plt.subplots(1, 2, figsize=figsize)
    lag = _get_ts_lag(config, series)
    plot_acf(series.dropna(), lags=lag, ax=axes[0], fft=True)
    plot_pacf(series.dropna(), lags=lag, ax=axes[1], method="ywm")
    fig.tight_layout()
    return _figure_to_base64(fig, config)


def _plot_acf_pacf_comparison(config, series: List[pd.Series], figsize: tuple = (15, 5)) -> str:
    fig, axes = plt.subplots(len(series), 2, figsize=(figsize[0], figsize[1] * len(series)))
