    fig.tight_layout()
    return _figure_to_base64(fig, config)


def missing_bar(notnull_counts: pd.Series, nrows: int, figsize: Tuple[float, float] = (25, 10), fontsize: float = 16, labels: bool = True, color: Tuple[float, ...] = (0.41, 0.41, 0.41), label_rotation: int = 45):
