import functools

import matplotlib

matplotlib.use("Agg")
import matplotlib.pyplot as plt


def manage_matplotlib_context():
    def decorator(fn):
        @functools.wraps(fn)
        def inner(*args, **kwargs):
            try:
                return fn(*args, **kwargs)
            finally:
                plt.close("all")

        return inner

    return decorator

