from __future__ import annotations

from typing import Any, Dict, List, Union

import pandas as pd


def _frequency_table(freqtable: pd.Series, n: int, max_number_to_print: int) -> List[Dict[str, Any]]:
    if freqtable is None or len(freqtable) == 0:
        return []
    freqtable = freqtable.sort_values(ascending=False)
    freqtable = freqtable.head(max_number_to_print)
    max_freq = max(int(freqtable.max()), 1)
    rows = []
    for label, count in freqtable.items():
        rows.append(
            {
                "label": str(label),
                "width": float(count) / max_freq,
                "count": int(count),
                "percentage": float(count) / max(n, 1),
                "n": n,
                "extra_class": "",
            }
        )
    return rows


def freq_table(freqtable: Union[pd.Series, List[pd.Series]], n: Union[int, List[int]], max_number_to_print: int) -> Union[List[Dict[str, Any]], List[List[Dict[str, Any]]]]:
    if isinstance(freqtable, list):
        n_values = n if isinstance(n, list) else [n] * len(freqtable)
        return [_frequency_table(table, total, max_number_to_print) for table, total in zip(freqtable, n_values)]
    return _frequency_table(freqtable, int(n), max_number_to_print)


def _extreme_obs_table(freqtable: pd.Series, number_to_print: int, n: int) -> List[Dict[str, Any]]:
    if freqtable is None or len(freqtable) == 0:
        return []
    sorted_table = freqtable.head(number_to_print)
    max_freq = max(int(sorted_table.max()), 1)
    return [
        {
            "label": str(label),
            "width": float(count) / max_freq,
            "count": int(count),
            "percentage": float(count) / max(n, 1),
            "extra_class": "",
            "n": n,
        }
        for label, count in sorted_table.items()
    ]


def extreme_obs_table(freqtable: Union[pd.Series, List[pd.Series]], number_to_print: int, n: Union[int, List[int]]) -> List[List[Dict[str, Any]]]:
    if isinstance(freqtable, list):
        n_values = n if isinstance(n, list) else [n] * len(freqtable)
        return [_extreme_obs_table(table, number_to_print, total) for table, total in zip(freqtable, n_values)]
    return [_extreme_obs_table(freqtable, number_to_print, int(n))]

from __future__ import annotations

import sys
from abc import ABC, abstractmethod
from types import ModuleType
from typing import Any, Callable, Dict, List, Optional, Sequence

import pandas as pd

from ydata_profiling.config import ImageType, Style


class Renderable(ABC):
    def __init__(
        self,
        content: Dict[str, Any],
        name: Optional[str] = None,
        anchor_id: Optional[str] = None,
        classes: Optional[str] = None,
    ):
        content = dict(content)
        if name is not None:
            content["name"] = name
        if anchor_id is not None:
            content["anchor_id"] = anchor_id
        if classes is not None:
            content["classes"] = classes
        self.content = content

    @property
    def name(self) -> str:
        return self.content.get("name", "")

    @property
    def anchor_id(self) -> str:
        return self.content.get("anchor_id", "")

    @property
    def classes(self) -> str:
        return self.content.get("classes", "")

    @abstractmethod
    def render(self) -> Any:
        raise NotImplementedError()

    def __str__(self) -> str:
        return self.__class__.__name__

    @classmethod
    def convert_to_class(cls, obj: "Renderable", flavour_func) -> None:
        obj.__class__ = cls


class ItemRenderer(Renderable, ABC):
    def __init__(
        self,
        item_type: str,
        content: dict,
        name: Optional[str] = None,
        anchor_id: Optional[str] = None,
        classes: Optional[str] = None,
    ):
        super().__init__(content, name=name, anchor_id=anchor_id, classes=classes)
        self.item_type = item_type


class HTML(ItemRenderer):
    def __init__(self, html: str, **kwargs):
        super().__init__("html", {"html": html}, **kwargs)

    def render(self) -> Any:
        raise NotImplementedError()


class Alerts(ItemRenderer):
    def __init__(self, alerts, style: Style, **kwargs):
        super().__init__("alerts", {"alerts": alerts, "style": style}, **kwargs)

    def __repr__(self) -> str:
        return "Alerts"

    def render(self) -> Any:
        raise NotImplementedError()


class ToggleButton(ItemRenderer):
    def __init__(self, text: str, **kwargs):
        super().__init__("toggle_button", {"text": text}, **kwargs)

    def __repr__(self) -> str:
        return "ToggleButton"

    def render(self) -> Any:
        raise NotImplementedError()


class Collapse(ItemRenderer):
    def __init__(self, button: ToggleButton, item: Renderable, **kwargs):
        super().__init__("collapse", {"button": button, "item": item}, **kwargs)

    def __repr__(self) -> str:
        return "Collapse"

    def render(self) -> Any:
        raise NotImplementedError()

    @classmethod
    def convert_to_class(cls, obj: Renderable, flv: Callable) -> None:
        obj.__class__ = cls
        flv(obj.content["button"])
        flv(obj.content["item"])


class Container(Renderable):
    def __init__(
        self,
        items: Sequence[Renderable],
        sequence_type: str,
        nested: bool = False,
        name: Optional[str] = None,
        anchor_id: Optional[str] = None,
        classes: Optional[str] = None,
        oss: Optional[bool] = None,
        **kwargs,
    ):
        content = {"items": list(items), "sequence_type": sequence_type, "nested": nested, "oss": oss}
        content.update(kwargs)
        super().__init__(content, name=name, anchor_id=anchor_id, classes=classes)

    @property
