from __future__ import annotations

import copy

from ydata_profiling.report.presentation.core import Renderable, Root

_FLAVOUR_REGISTRY: dict = {}


def register_flavour(name: str, mapping: dict) -> None:
    _FLAVOUR_REGISTRY[name] = mapping


def get_flavour_mapping(name: str) -> dict:
    if name not in _FLAVOUR_REGISTRY:
        raise ValueError(f"Unknown flavour: {name}")
    return _FLAVOUR_REGISTRY[name]


def apply_renderable_mapping(mapping: dict, structure: Renderable, flavour_func) -> None:
    for core_cls, flavour_cls in mapping.items():
        if isinstance(structure, core_cls):
            flavour_cls.convert_to_class(structure, flavour_func)
            return


def HTMLReport(structure: Root) -> Root:
    from ydata_profiling.report.presentation.flavours import flavour_html  # noqa: F401

    clone = copy.deepcopy(structure)
    mapping = get_flavour_mapping("html")
    apply_renderable_mapping(mapping, clone, lambda item: apply_renderable_mapping(mapping, item, lambda inner: apply_renderable_mapping(mapping, inner, lambda _: None)))
    return clone


def WidgetReport(structure: Root) -> Root:
    from ydata_profiling.report.presentation.flavours import flavour_widget  # noqa: F401

    clone = copy.deepcopy(structure)
    mapping = get_flavour_mapping("widget")
    apply_renderable_mapping(mapping, clone, lambda item: apply_renderable_mapping(mapping, item, lambda inner: apply_renderable_mapping(mapping, inner, lambda _: None)))
    return clone

