def get_name(item) -> str:
    return item.name or item.anchor_id


def get_tabs(items: List) -> widgets.Tab:
    tab = widgets.Tab(children=[item.render() for item in items])
    for index, item in enumerate(items):
        tab.set_title(index, get_name(item))
    return tab


def get_list(items: List) -> widgets.VBox:
    return widgets.VBox(children=[item.render() for item in items])


def get_named_list(items: List) -> widgets.VBox:
    children = []
    for item in items:
        children.append(widgets.HTML(value=f"<h4>{get_name(item)}</h4>"))
        children.append(item.render())
    return widgets.VBox(children=children)


def get_row(items: List) -> widgets.GridBox:
    count = len(items)
    if count > 4:
        raise ValueError("Only up to 4 columns are supported")
    templates = {
        1: "100%",
        2: "50% 50%",
        3: "25% 25% 50%",
        4: "25% 25% 25% 25%",
    }
    return widgets.GridBox(
        children=[item.render() for item in items],
        layout=widgets.Layout(grid_template_columns=templates[count], grid_gap="1rem"),
    )


def get_batch_grid(items: List, batch_size: int, titles: bool, subtitles: bool) -> widgets.GridBox:
    children = []
    for item in items:
        if titles:
            children.append(widgets.VBox(children=[widgets.HTML(value=f"<h4>{item.name}</h4>"), item.render()]))
        elif subtitles:
            children.append(widgets.VBox(children=[widgets.HTML(value=f"<h5><i>{item.name}</i></h5>"), item.render()]))
        else:
            children.append(item.render())
    return widgets.GridBox(
        children=children,
        layout=widgets.Layout(grid_template_columns=" ".join([f"{100 / max(batch_size, 1):.2f}%"] * max(batch_size, 1)), grid_gap="1rem"),
    )


def get_accordion(items: List) -> widgets.Accordion:
    accordion = widgets.Accordion(children=[item.render() for item in items])
    for index, item in enumerate(items):
        accordion.set_title(index, get_name(item))
    return accordion


def frequency_table_nb(rows: List[List[dict]]) -> widgets.VBox:
    batches = rows if rows and isinstance(rows[0], list) else [rows]
    row_widgets = []
    for batch in batches:
        children = []
        for row in batch:
            style = "danger" if row.get("extra_class") == "missing" else "info" if row.get("extra_class") == "other" else ""
            progress = widgets.FloatProgress(value=row.get("percentage", 0.0), min=0.0, max=1.0, description=row.get("label", ""), bar_style=style)
            children.append(widgets.HBox(children=[progress, widgets.Label(value=str(row.get("count", 0)))]))
        row_widgets.append(widgets.VBox(children=children))
    return widgets.VBox(children=row_widgets)


class WidgetAlerts(Alerts):
    def render(self) -> widgets.GridBox:
        alerts = self.content["alerts"]
        alerts = alerts if isinstance(alerts, list) else [item for group in alerts.values() for item in group]
        buttons = [
            widgets.Button(description=alert.fmt(), button_style=get_alert_styles().get(alert.alert_type_name, ""))
            for alert in alerts
        ]
        return widgets.GridBox(children=buttons)


