            "accordion": get_accordion,
            "grid": lambda items: get_batch_grid(items, batch_size=2, titles=False, subtitles=False),
            "batch_grid": lambda items: get_batch_grid(items, batch_size=2, titles=False, subtitles=False),
        }
        return mapping[self.sequence_type](self.content["items"])


