                f'<div id="{self.content["anchor_id"]}"><h4>{self.content["var_name"]}</h4>'
                f'<p><strong>{self.content["var_type"]}</strong></p><p>{self.content["description"]}</p>'
                f"<ul>{alerts}</ul></div>"
            )
        )


def get_notebook_iframe_srcdoc(config, profile):
    return IPyHTML(
        f'<iframe srcdoc="{profile.to_html().replace(chr(34), "&quot;")}" '
        f'style="width:{config.notebook.iframe.width};height:{config.notebook.iframe.height};border:none;"></iframe>'
    )


def get_notebook_iframe_src(config, profile):
    from pathlib import Path

    tmp_dir = Path("./tmp")
    tmp_dir.mkdir(exist_ok=True)
    path = tmp_dir / f"profile_{abs(hash(profile.to_html()))}.html"
    path.write_text(profile.to_html())
    return IFrame(str(path), width=config.notebook.iframe.width, height=config.notebook.iframe.height)


def get_notebook_iframe(config, profile):
    if config.notebook.iframe.attribute.value == "src":
        return get_notebook_iframe_src(config, profile)
    return get_notebook_iframe_srcdoc(config, profile)


