def _df_to_html(df: pd.DataFrame) -> str:
    if df is None or len(df) == 0:
        return "<table class='table'><tr><td>No data</td></tr></table>"
    return df.to_html(index=False, classes="table", border=0)


class HTMLAlerts(Alerts):
    def render(self) -> str:
        alerts = self.content["alerts"]
        alerts = alerts if isinstance(alerts, list) else [item for group in alerts.values() for item in group]
        return template("alerts.html").render(alerts=alerts, styles=get_alert_styles())


class HTMLCollapse(Collapse):
    def render(self) -> str:
        return template("collapse.html").render(button=self.content["button"].render(), item=self.content["item"].render())


class HTMLContainer(Container):
    def render(self) -> str:
        mapping = {
            "list": "sequence/list.html",
            "named_list": "sequence/named_list.html",
            "sections": "sequence/sections.html",
            "tabs": "sequence/tabs.html",
            "select": "sequence/select.html",
            "accordion": "sequence/accordion.html",
            "grid": "sequence/grid.html",
            "batch_grid": "sequence/batch_grid.html",
        }
        template_name = mapping.get(self.sequence_type)
        if template_name is None:
            raise ValueError(f"Unknown sequence type: {self.sequence_type}")
        return template(template_name).render(items=[item.render() for item in self.content["items"]])


class HTMLCorrelationTable(CorrelationTable):
    def render(self) -> str:
        table_html = self.content["correlation_matrix"].round(3).to_html(classes="table", border=0)
        return template("correlation_table.html").render(name=self.name, table=table_html)


