    def render(self) -> str:
        return template("duplicate.html").render(name=self.name, table=_df_to_html(self.content["duplicate"]))


class HTMLFrequencyTable(FrequencyTable):
    def render(self) -> str:
        rows = self.content["rows"]
        if rows and isinstance(rows[0], list):
            return "".join(template("frequency_table.html").render(rows=batch) for batch in rows)
        return template("frequency_table.html").render(rows=rows)


class HTMLFrequencyTableSmall(FrequencyTableSmall):
    def render(self) -> str:
        rows = self.content["rows"]
        if rows and isinstance(rows[0], list):
            return "".join(template("frequency_table_small.html").render(rows=batch) for batch in rows)
        return template("frequency_table_small.html").render(rows=rows)


class HTMLRoot(Root):
    def render(self, **kwargs) -> str:
        body = self.content["body"].render()
        footer = self.content["footer"].render()
        body_items = getattr(self.content["body"], "content", {}).get("items", [])
        navigation = [{"name": item.name, "anchor_id": item.anchor_id} for item in body_items if getattr(item, "anchor_id", None)]
        return template("report.html").render(name=self.name, body=body, footer=footer, navigation=navigation, **kwargs)


class HTMLSample(Sample):
