from __future__ import annotations

import json
from datetime import datetime
from typing import Any

from ydata_profiling.report.formatters import fmt_bytesize, fmt_number, fmt_timespan
from ydata_profiling.report.presentation.core import Alerts, Container, HTML, Image, Table


def get_dataset_overview(config, summary) -> Container:
    table = summary.table
    rows = [
        ("Number of variables", fmt_number(table.get("n_var", 0))),
        ("Number of observations", fmt_number(table.get("n", 0))),
        ("Missing cells", fmt_number(table.get("n_cells_missing", 0))),
        ("Duplicates", fmt_number(table.get("n_duplicates", 0))),
        ("Memory size", fmt_bytesize(table.get("memory_size", 0))),
    ]
    types_rows = [(key, fmt_number(value)) for key, value in table.get("types", {}).items()]
    return Container(
        [
            Table(rows=rows, style=config.html.style, name="Overview"),
            Table(rows=types_rows, style=config.html.style, name="Variable types"),
        ],
        sequence_type="grid",
        name="Dataset Overview",
        anchor_id="overview",
    )


def get_dataset_schema(config, metadata: dict) -> Container:
    rows = [(key.replace("_", " ").title(), value) for key, value in metadata.items() if value]
    return Container([Table(rows=rows, style=config.html.style, name="Schema")], sequence_type="list", name="Dataset Schema", anchor_id="schema")


def get_dataset_reproduction(config, summary) -> Container:
    def fmt_version(version: str) -> str:
        return f'<a href="https://github.com/ydataai/ydata-profiling">{version}</a>'

    def fmt_config(config_str: str) -> str:
        return f'<a download="config.json" href="data:application/json,{config_str}">config.json</a>'

    rows = [
        ("Title", summary.analysis.title),
        ("Started", str(summary.analysis.date_start)),
        ("Finished", str(summary.analysis.date_end)),
        ("Duration", fmt_timespan(summary.analysis.duration.total_seconds() if not isinstance(summary.analysis.duration, list) else 0)),
        ("Version", fmt_version(summary.package.get("ydata_profiling_version", ""))),
        ("Config", fmt_config(json.dumps(summary.package.get("ydata_profiling_config", {})))),
    ]
    return Container([Table(rows=rows, style=config.html.style, name="Reproduction")], sequence_type="list", name="Reproduction", anchor_id="reproduction")


def get_dataset_column_definitions(config, definitions: dict) -> Container:
    rows = [(key, value) for key, value in definitions.items()]
    return Container([Table(rows=rows, style=config.html.style, name="Column definitions")], sequence_type="list", name="Column Definitions", anchor_id="definitions")


def get_dataset_alerts(config, alerts: list) -> Alerts:
    return Alerts(alerts=alerts, style=config.html.style, name=f"Alerts ({len(alerts)})", anchor_id="alerts")


def fmt_tsindex_limit(limit: Any) -> str:
    if isinstance(limit, datetime):
        return limit.strftime("%Y-%m-%d %H:%M:%S")
    return fmt_number(limit) if isinstance(limit, (int, float)) else str(limit)


def get_timeseries_items(config, summary) -> Container:
    if summary.time_index_analysis is None:
        return Container([], sequence_type="list", name="Time Series", anchor_id="timeseries")
    ts = summary.time_index_analysis
    rows = [
        ("Series", fmt_number(ts.n_series)),
        ("Length", fmt_number(ts.length)),
        ("Start", fmt_tsindex_limit(ts.start)),
        ("End", fmt_tsindex_limit(ts.end)),
        ("Period", str(ts.period)),
        ("Frequency", str(ts.frequency)),
    ]
    return Container([Table(rows=rows, style=config.html.style, name="Time index")], sequence_type="list", name="Time Series", anchor_id="timeseries")


def get_dataset_items(config, summary, alerts: list) -> list:
    items = [get_dataset_overview(config, summary)]
    metadata = summary.package.get("ydata_profiling_config", {}).get("dataset", {})
    if metadata:
        items.append(get_dataset_schema(config, metadata))
    definitions = summary.package.get("ydata_profiling_config", {}).get("variables", {}).get("descriptions", {})
    if definitions:
        items.append(get_dataset_column_definitions(config, definitions))
    if summary.time_index_analysis is not None:
        items.append(get_timeseries_items(config, summary))
    if alerts:
        items.append(get_dataset_alerts(config, alerts))
    items.append(get_dataset_reproduction(config, summary))
    return items

