def render_common(config, summary: dict) -> dict:
    rows = [
        ("Type", summary.get("type", "Unknown")),
        ("Count", fmt_number(summary.get("n", 0))),
        ("Missing", fmt_number(summary.get("n_missing", 0))),
        ("Distinct", fmt_number(summary.get("n_distinct", 0))),
        ("Unique", fmt_number(summary.get("n_unique", 0))),
        ("Memory", fmt_bytesize(summary.get("memory_size", 0))),
    ]
    return {
        "common": Table(rows=rows, style=config.html.style, name="Common statistics"),
    }


def _get_n(value: Union[list, pd.DataFrame]) -> Union[int, List[int]]:
    if isinstance(value, list):
        return [int(item.sum()) if hasattr(item, "sum") else 0 for item in value]
    return int(value.sum()) if hasattr(value, "sum") else 0


def render_count(config, summary: dict) -> dict:
    vc = summary.get("value_counts_without_nan")
    if vc is None or len(vc) == 0:
        return {"top": render_common(config, summary)["common"], "bottom": None}
    rows = freq_table(vc, _get_n(vc), config.n_freq_table_max)
    return {
        "top": render_common(config, summary)["common"],
        "bottom": FrequencyTable(rows=rows, redact=False, name="Frequency"),
    }


def render_categorical_frequency(config, summary: dict, varid: str):
    rows = [
        ("Distinct", fmt_number(summary.get("n_distinct", 0))),
        ("Unique", fmt_number(summary.get("n_unique", 0))),
        ("Top", str(summary.get("top", ""))),
    ]
    return Table(rows=rows, style=config.html.style, name="Frequency statistics", anchor_id=f"{varid}-frequency")


def render_categorical_length(config, summary: dict, varid: str) -> Tuple[Any, Any]:
    rows = [
        ("Max length", fmt_number(summary.get("max_length", 0))),
        ("Mean length", fmt_numeric(summary.get("mean_length", 0))),
        ("Median length", fmt_numeric(summary.get("median_length", 0))),
        ("Min length", fmt_number(summary.get("min_length", 0))),
    ]
    hist = summary.get("histogram_length", {})
    hist_img = None
    if hist:
        hist_img = Image(
            image=mini_histogram(config, np.repeat(np.arange(len(hist.get("counts", []))), hist.get("counts", [])) if len(hist.get("counts", [])) else np.array([]), hist.get("bins", [])),
            image_format=config.plot.image_format,
            alt="Length histogram",
            caption="Length distribution",
        )
    return Table(rows=rows, style=config.html.style, name="Length statistics", anchor_id=f"{varid}-length"), hist_img


def render_categorical_unicode(config, summary: dict, varid: str) -> Tuple[Any, Any]:
    rows = [
        ("Distinct characters", fmt_number(summary.get("n_characters_distinct", 0))),
        ("Characters", fmt_number(summary.get("n_characters", 0))),
    ]
    word_counts = summary.get("character_counts")
    table = FrequencyTableSmall(rows=freq_table(word_counts, _get_n(word_counts), config.n_freq_table_max) if word_counts is not None else [], redact=False, name="Character counts")
    return Table(rows=rows, style=config.html.style, name="Unicode statistics", anchor_id=f"{varid}-unicode"), table


def render_categorical(config, summary: dict) -> dict:
    varid = slugify(summary.get("name", "categorical"))
    parts = [render_common(config, summary)["common"], render_categorical_frequency(config, summary, varid)]
    if config.vars.cat.length:
        length_table, length_hist = render_categorical_length(config, summary, varid)
        parts.append(length_table)
        if length_hist is not None:
            parts.append(length_hist)
    if config.vars.cat.characters:
        unicode_table, unicode_view = render_categorical_unicode(config, summary, varid)
        parts.extend([unicode_table, unicode_view])
    if summary.get("word_counts") is not None and len(summary.get("word_counts")):
        parts.append(Image(image=plot_word_cloud(config, summary["word_counts"]), image_format=config.plot.image_format, alt="Word cloud", caption="Word cloud"))
    if config.plot.cat_freq.show and summary.get("value_counts_without_nan") is not None and summary.get("n_distinct", 0) <= config.plot.cat_freq.max_unique:
        parts.append(Image(image=cat_frequency_plot(config, summary["value_counts_without_nan"]), image_format=config.plot.image_format, alt="Category frequency plot", caption="Category distribution"))
    return {"top": Container(parts[:2], sequence_type="list"), "bottom": Container(parts[2:], sequence_type="list") if len(parts) > 2 else None}


