from __future__ import annotations

from typing import List, Sequence

import pandas as pd

from ydata_profiling.model.handler import get_render_map
from ydata_profiling.report.presentation.core import Container, Duplicate, HTML, Image, Root, Sample, Variable, VariableInfo
from ydata_profiling.report.structure.correlations import get_correlation_items
from ydata_profiling.report.structure.overview import get_dataset_items
from ydata_profiling.utils.dataframe import slugify


def get_missing_items(config, summary) -> list:
    items = []
    for name, diagram in summary.missing.items():
        items.append(Image(image=diagram["image"], image_format=config.plot.image_format, alt=name, caption=diagram.get("caption"), name=name))
    return items


def get_duplicates_items(config, duplicates: pd.DataFrame) -> List:
    if duplicates is None:
        return []
    if isinstance(duplicates, tuple):
        return [Duplicate(name=f"Duplicates {index + 1}", duplicate=value) for index, value in enumerate(duplicates)]
    return [Duplicate(name="Duplicates", duplicate=duplicates)]


def get_definition_items(definitions: pd.DataFrame) -> Sequence:
    if definitions is None:
        return []
    return [HTML(definitions.to_html(index=False), name="Definitions")]


def get_sample_items(config, sample: dict) -> List:
    if isinstance(sample, tuple):
        items = []
        for index, samples in enumerate(sample):
            items.extend([Sample(name=f"{item.name} {index + 1}", sample=item.data, caption=item.caption) for item in samples])
        return items
    return [Sample(name=item.name, sample=item.data, caption=item.caption) for item in sample]


def get_interactions(config, interactions: dict) -> list:
    items = []
    for left, nested in interactions.items():
        nested_items = [HTML(html=image, name=f"{left} vs {right}") for right, image in nested.items() if image]
        if nested_items:
            items.append(Container(nested_items, sequence_type="grid", name=left))
    return items


def render_variables_section(config, dataframe_summary) -> list:
    render_map = get_render_map()
    variables = []
    for name, summary in dataframe_summary.variables.items():
        render_data = render_map.get(summary.get("type"), render_map["Unsupported"])(config, summary)
        description = config.variables.descriptions.get(name, "") if hasattr(config.variables, "descriptions") else ""
        info = VariableInfo(
            anchor_id=slugify(name),
            var_name=name,
            var_type=summary.get("type", "Unknown"),
            alerts=[alert for alert in dataframe_summary.alerts if getattr(alert, "column_name", None) == name],
            description=description,
            style=config.html.style,
        )
        top = Container([info, render_data["top"]] if render_data.get("top") is not None else [info], sequence_type="list")
        variables.append(Variable(top=top, bottom=render_data.get("bottom"), name=name, anchor_id=slugify(name)))
    return variables


def get_report_structure(config, summary) -> Root:
    alerts = summary.alerts
    sections = []
    sections.append(Container(get_dataset_items(config, summary, alerts), sequence_type="sections", name="Overview", anchor_id="overview-section"))
    variable_items = render_variables_section(config, summary)
    if variable_items:
        sections.append(Container(variable_items, sequence_type="list", name="Variables", anchor_id="variables"))
    correlation_items = get_correlation_items(config, summary)
    if correlation_items:
        sections.append(Container(correlation_items, sequence_type="list", name="Correlations", anchor_id="correlations"))
    missing_items = get_missing_items(config, summary)
    if missing_items:
        sections.append(Container(missing_items, sequence_type="grid", name="Missing values", anchor_id="missing"))
    sample_items = get_sample_items(config, summary.sample)
    if sample_items:
        sections.append(Container(sample_items, sequence_type="list", name="Samples", anchor_id="samples"))
    duplicate_items = get_duplicates_items(config, summary.duplicates)
    if duplicate_items:
        sections.append(Container(duplicate_items, sequence_type="list", name="Duplicates", anchor_id="duplicates"))
    interaction_items = get_interactions(config, summary.scatter)
    if interaction_items:
        sections.append(Container(interaction_items, sequence_type="grid", name="Interactions", anchor_id="interactions"))
    body = Container(sections, sequence_type="sections", name="Report body")
    footer = HTML("<footer><p>Generated by ydata-profiling</p></footer>", name="Footer")
    return Root(name=summary.analysis.title, body=body, footer=footer, style=config.html.style)

