from __future__ import annotations

from copy import deepcopy
from dataclasses import asdict, is_dataclass
from typing import Any, List, Optional, Tuple, Union

import pandas as pd

from ydata_profiling.model.description import BaseAnalysis, BaseDescription, TimeIndexAnalysis
from ydata_profiling.report.presentation.core import Container, HTML, Root, Table


def _should_wrap(v1: Any, v2: Any) -> bool:
    if isinstance(v1, (list, dict)) or isinstance(v2, (list, dict)):
        return False
    if isinstance(v1, (pd.DataFrame, pd.Series)) and isinstance(v2, type(v1)):
        return not v1.equals(v2)
    try:
        return v1 != v2
    except ValueError:
        return True


def _update_merge_seq(d1: Any, d2: Any) -> Union[list, tuple]:
    if isinstance(d1, tuple):
        left = list(d1)
    elif isinstance(d1, list):
        left = d1
    else:
        left = [d1]
    if isinstance(d2, tuple):
        right = list(d2)
    elif isinstance(d2, list):
        right = d2
    else:
        right = [d2]
    if isinstance(d1, tuple) or isinstance(d2, tuple):
        return tuple(left + right)
    return left + right


def _update_merge_mixed(d1: Any, d2: Any) -> Union[dict, list, tuple]:
    if isinstance(d1, dict) and isinstance(d2, dict):
        return _update_merge_dict(d1, d2)
    return _update_merge_seq(d1, d2)


def _update_merge_dict(d1: Any, d2: Any) -> dict:
    merged = {**deepcopy(d1), **deepcopy(d2)}
    for key in set(d1).intersection(d2):
        v1 = d1[key]
        v2 = d2[key]
        if isinstance(v1, dict) and isinstance(v2, dict):
            merged[key] = _update_merge_dict(v1, v2)
        elif _should_wrap(v1, v2):
            merged[key] = _update_merge_mixed(v1, v2)
        else:
            merged[key] = deepcopy(v1)
    return merged


def _update_merge(d1: Optional[dict], d2: dict) -> dict:
    if d1 is None:
        return deepcopy(d2)
    if not isinstance(d1, dict) or not isinstance(d2, dict):
        raise TypeError("Both inputs must be dictionaries")
    return _update_merge_dict(d1, d2)


def _placeholders(reports: List[BaseDescription]) -> None:
    scatter_keys = set()
    type_keys = set()
    for report in reports:
        scatter_keys.update(report.scatter.keys())
        type_keys.update(report.table.get("types", {}).keys())
    for report in reports:
        for key in scatter_keys:
            report.scatter.setdefault(key, {})
        for key in type_keys:
            report.table.setdefault("types", {}).setdefault(key, 0)


def _update_titles(reports: List) -> None:
    for index, report in enumerate(reports):
        if getattr(report.config, "title", "") == "YData Profiling Report":
            report.config.title = f"Dataset {chr(65 + index)}"


def _compare_profile_report_preprocess(reports: List, config=None) -> Tuple[List[str], List[BaseDescription]]:
    _update_titles(reports)
    labels = [report.config.title for report in reports]
    descriptions = [report.get_description() for report in reports]
    if config is not None:
        config.html.style._labels = labels
    else:
        reports[0].config.html.style._labels = labels
    for label, description in zip(labels, descriptions):
        description.analysis.title = label
    return labels, descriptions


def _compare_dataset_description_preprocess(reports: List[BaseDescription]) -> Tuple[List[str], List[BaseDescription]]:
    return [report.analysis.title for report in reports], reports


def _apply_config(description: BaseDescription, config) -> BaseDescription:
    return description


def _is_alert_present(alert, alert_list: list) -> bool:
    return any(existing.column_name == alert.column_name and existing.alert_type == alert.alert_type for existing in alert_list)


def _create_placehoder_alerts(report_alerts: tuple) -> tuple:
    return report_alerts


def _compare_title(titles: List[str]) -> str:
    return " vs ".join(titles)


def validate_reports(reports: Union[List, List[BaseDescription]], configs: List[dict]) -> None:
    if len(reports) < 2:
        raise ValueError("At least two reports are required for comparison")
    if len(reports) > 2:
        import warnings

        warnings.warn("Comparing more than two reports is only partially supported.")


def _to_dict(description: BaseDescription) -> dict:
    def convert(value: Any):
        if is_dataclass(value):
            return {key: convert(val) for key, val in asdict(value).items()}
        if isinstance(value, dict):
            return {key: convert(val) for key, val in value.items()}
        return value

    return convert(description)


def compare(reports: Union[List, List[BaseDescription]], config=None, compute: bool = False):
    from ydata_profiling.profile_report import ProfileReport

    configs = [getattr(report, "config", {}).dict() if hasattr(getattr(report, "config", None), "dict") else {} for report in reports]
    validate_reports(reports, configs)
    if reports and hasattr(reports[0], "get_description"):
        labels, descriptions = _compare_profile_report_preprocess(reports, config=config)
        base_config = config or reports[0].config.copy(deep=True)
    else:
        labels, descriptions = _compare_dataset_description_preprocess(reports)
        from ydata_profiling.config import Settings

        base_config = config or Settings()

    _placeholders(descriptions)
    merged: Optional[dict] = None
    for description in descriptions:
        merged = _update_merge(merged, _to_dict(description))
    assert merged is not None

    analysis = BaseAnalysis(
        title=_compare_title(labels),
        date_start=[description.analysis.date_start for description in descriptions],
        date_end=[description.analysis.date_end for description in descriptions],
    )
    time_index = None
    if any(description.time_index_analysis is not None for description in descriptions):
        time_index = TimeIndexAnalysis(
            n_series=[getattr(description.time_index_analysis, "n_series", 0) if description.time_index_analysis else 0 for description in descriptions],
            length=[getattr(description.time_index_analysis, "length", 0) if description.time_index_analysis else 0 for description in descriptions],
            start=[getattr(description.time_index_analysis, "start", None) if description.time_index_analysis else None for description in descriptions],
            end=[getattr(description.time_index_analysis, "end", None) if description.time_index_analysis else None for description in descriptions],
            period=[getattr(description.time_index_analysis, "period", None) if description.time_index_analysis else None for description in descriptions],
            frequency=[getattr(description.time_index_analysis, "frequency", None) if description.time_index_analysis else None for description in descriptions],
        )
    merged_description = BaseDescription(
        analysis=analysis,
        time_index_analysis=time_index,
        table=merged["table"],
        variables=merged["variables"],
        scatter=merged["scatter"],
        correlations=merged["correlations"],
        missing=merged["missing"],
        alerts=tuple(description.alerts for description in descriptions),
        package=merged["package"],
        sample=tuple(description.sample for description in descriptions),
        duplicates=tuple(description.duplicates for description in descriptions),
    )

    report = ProfileReport(df=None, config=base_config, lazy=True)
    report._description_set = merged_description
    comparison_rows = [("Title", label) for label in labels]
    comparison_rows.extend(
        [
            (f"{label} rows", description.table.get("n", 0))
            for label, description in zip(labels, descriptions)
        ]
    )
    root = Root(
        name=analysis.title,
        body=Container(
            [
                Table(rows=comparison_rows, style=base_config.html.style, name="Comparison overview", anchor_id="comparison-overview"),
                HTML("<p>Comparison report generated from multiple profiling summaries.</p>", name="Notes", anchor_id="comparison-notes"),
            ],
            sequence_type="sections",
        ),
        footer=HTML("<footer><p>Generated by ydata-profiling</p></footer>", name="Footer"),
        style=base_config.html.style,
    )
    report._report = root
    return report

