try:
    from pyspark.sql import DataFrame as sDataFrame
except Exception:  # pragma: no cover
    class sDataFrame:  # type: ignore
        pass

try:
    from typeguard import typechecked
except Exception:  # pragma: no cover
    def typechecked(cls):
        return cls


@typechecked
class ProfileReport(SerializeReport, ExpectationsReport):
    """Generate a profile report from a Dataset stored as a pandas `DataFrame`."""

    _description_set = None
    _report = None
    _html = None
    _widgets = None
    _json = None
    config: Settings

    def __init__(
        self,
        df: Optional[Union[pd.DataFrame, sDataFrame]] = None,
        minimal: bool = False,
        tsmode: bool = False,
        sortby: Optional[str] = None,
        sensitive: bool = False,
        explorative: bool = False,
        sample: Optional[dict] = None,
        config_file: Optional[Union[Path, str]] = None,
        lazy: bool = True,
        typeset: Optional[ProfilingTypeSet] = None,
        summarizer: Optional[ProfilingSummarizer] = None,
        config: Optional[Settings] = None,
        type_schema: Optional[dict] = None,
        **kwargs,
    ):
        self.__validate_inputs(df, minimal, tsmode, config_file, lazy)
        self.df = None
        self._sample_arg = sample

        if config is not None:
            report_config = config.copy(deep=True)
        else:
            if config_file is not None:
                report_config = Settings.from_file(config_file)
            elif minimal:
                report_config = Settings.from_file(get_config("config_minimal.yaml"))
            else:
                report_config = Settings.from_file(get_config("config_default.yaml"))

        if sensitive:
            report_config = report_config.update(Config.get_arg_groups("sensitive"))
        if explorative:
            report_config = report_config.update(Config.get_arg_groups("explorative"))
        if tsmode:
            report_config = report_config.update({"vars": {"timeseries": {"active": True, "sortby": sortby}}})
        shorthand_updates, remaining_kwargs = Config.shorthands(kwargs)
        if shorthand_updates:
            report_config = report_config.update(shorthand_updates)
        if remaining_kwargs:
            report_config = report_config.update(remaining_kwargs)
        if "title" in kwargs:
            report_config.title = kwargs["title"]

        self.config = report_config
        self.df = self.__initialize_dataframe(df, report_config)
        self._typeset = typeset or ProfilingTypeSet(report_config, type_schema=type_schema)
        use_spark = isinstance(self.df, sDataFrame)
        self._summarizer = summarizer or ProfilingSummarizer(self._typeset, use_spark=use_spark)
        if not lazy and self.df is not None:
            _ = self.report
        display_banner()

    @staticmethod
    def __validate_inputs(df, minimal: bool, tsmode: bool, config_file: Optional[Union[Path, str]], lazy: bool) -> None:
        if minimal and config_file is not None:
            raise ValueError("`minimal=True` and `config_file` are mutually exclusive.")
        if isinstance(df, pd.DataFrame) and df.empty:
            raise ValueError("DataFrame is empty. Please provide a non-empty DataFrame.")
        if tsmode and isinstance(df, sDataFrame):
            raise ValueError("Time-series mode is only supported for pandas DataFrames.")
        if not isinstance(lazy, bool):
            raise TypeError("`lazy` must be a boolean.")

    @staticmethod
    def __initialize_dataframe(df, report_config: Settings):
        if df is None:
            return None
        frame = preprocess(report_config, df)
        if report_config.vars.timeseries.sortby and isinstance(frame, pd.DataFrame) and report_config.vars.timeseries.sortby in frame.columns:
            frame = frame.sort_values(report_config.vars.timeseries.sortby)
        return frame

    @property
    def typeset(self) -> Optional[ProfilingTypeSet]:
        return self._typeset

    @property
    def summarizer(self) -> ProfilingSummarizer:
        return self._summarizer

    @property
    def description_set(self):
        return self.get_description()

    @property
    def report(self):
        if self._report is None:
            self._report = get_report_structure(self.config, self.get_description())
        return self._report

    @property
    def html(self) -> str:
        if self._html is None:
            self._html = self._render_html()
        return self._html

    @property
    def json(self) -> str:
        if self._json is None:
            self._json = self._render_json()
        return self._json

    @property
    def widgets(self) -> Any:
        if self._widgets is None:
            self._widgets = self._render_widgets()
        return self._widgets

    def invalidate_cache(self, subset: Optional[str] = None) -> None:
        if subset == "rendering":
            self._html = None
            self._json = None
            self._widgets = None
        elif subset == "report":
            self._report = None
        else:
            self._html = None
            self._json = None
            self._widgets = None
            self._report = None
            self._description_set = None

    def get_duplicates(self):
        return self.get_description().duplicates

    def get_sample(self) -> dict:
        return {item.name: item.data for item in self.get_description().sample}

    def get_description(self):
        if self._description_set is None:
            if self.df is None:
                raise ValueError("No dataframe is associated with this report.")
            self._description_set = describe(self.config, self.df, self.summarizer, self.typeset, sample=self._sample_arg)
        return self._description_set

    def get_rejected_variables(self) -> set:
        description = self.get_description()
        return {name for name, summary in description.variables.items() if summary.get("type") == "Unsupported"}

    def _render_html(self) -> str:
        return HTMLReport(self.report).render()

    def _render_widgets(self) -> Any:
        return WidgetReport(self.report).render()

    def _render_json(self) -> str:
        return json.dumps(format_summary(self.get_description()), default=str)

    def to_file(self, output_file: Union[str, Path], silent: bool = True) -> None:
        output_path = Path(output_file)
        if output_path.suffix.lower() == ".json":
            output_path.write_text(self.to_json())
        else:
            output_path.write_text(self.to_html())
            if not self.config.html.inline:
                create_html_assets(self.config, output_path)
        if not silent:
            try:
                webbrowser.open(output_path.resolve().as_uri())
            except Exception:
                pass

    def to_html(self) -> str:
        return self.html

    def to_json(self) -> str:
        return self.json

    def to_notebook_iframe(self) -> None:
        from ydata_profiling.report.presentation.flavours.widget.notebook import get_notebook_iframe

        return get_notebook_iframe(self.config, self)

    def to_widgets(self) -> Any:
        return self.widgets

    def compare(self, other: "ProfileReport", config: Optional[Settings] = None) -> "ProfileReport":
        return compare([self, other], config=config)

    def __repr__(self) -> str:
        return ""

    def _repr_html_(self) -> str:
        return self.to_html()


def compare(reports, config: Optional[Settings] = None, compute: bool = False) -> ProfileReport:
    from ydata_profiling.compare_reports import compare as compare_reports

    return compare_reports(reports, config=config, compute=compute)

